class BillboardCollection(ResiumComponent):
    """Wraps resium ``BillboardCollection``.

    BillboardCollection is a collection of billboard primitives. It can have some
    Billboard components as children.

    Scope:
      Inside Viewer or CesiumWidget components.
      A BillboardColleciton object will be attached to the PrimitiveCollection of the Viewer or CesiumWidget.

    Docs: https://resium.reearth.io/components/BillboardCollection
    """

    tag = "BillboardCollection"

    # Determines if billboards in this collection will be shown. Type: boolean.
    show: rx.Var[bool]

    # The billboard blending option. The default is used for rendering both opaque and translucent
    # billboards. However, if either all of the billboards are completely opaque or all are
    # completely translucent, setting the technique to BlendOption.OPAQUE or
    # BlendOption.TRANSLUCENT can improve performance by up to 2x. Type: BlendOption.
    blend_option: rx.Var[float]

    # The distance from the camera, beyond which, billboards are depth-tested against an
    # approximation of the globe ellipsoid rather than against the full globe depth buffer. When
    # set to <code>0</code>, the approximate depth test is always applied. When set to
    # <code>Number.POSITIVE_INFINITY</code>, the approximate depth test is never applied.
    # <br/><br/> This setting only applies when a billboard's {@link
    # Billboard#disableDepthTestDistance } value would otherwise allow depth testing—i.e.,
    # distance from the camera to the billboard is less than a billboard's {@link
    # Billboard#disableDepthTestDistance } value. Type: number.
    coarse_depth_test_distance: rx.Var[float]

    # This property is for debugging only; it is not for production use nor is it optimized. <p>
    # Draws the bounding sphere for each draw command in the primitive. </p> Type: boolean.
    debug_show_bounding_volume: rx.Var[bool]

    # This property is for debugging only; it is not for production use nor is it optimized. <p>
    # Draws the texture atlas for this BillboardCollection as a fullscreen quad. </p> Type:
    # boolean.
    debug_show_texture_atlas: rx.Var[bool]

    # The 4x4 transformation matrix that transforms each billboard in this collection from model
    # to world coordinates. When this is the identity matrix, the billboards are drawn in world
    # coordinates, i.e., Earth's WGS84 coordinates. Local reference frames can be used by
    # providing a different transformation matrix, like that returned by {@link
    # Transforms.eastNorthUpToFixedFrame}. Type: Matrix4.
    model_matrix: rx.Var[Any]

    # The distance from the camera, within which, billboards with a {@link
    # Billboard#heightReference } value of {@link HeightReference.CLAMP_TO_GROUND} or {@link
    # HeightReference.CLAMP_TO_TERRAIN} are depth tested against three key points. This ensures
    # that if any key point of the billboard is visible, the whole billboard will be visible. When
    # set to <code>0</code>, this feature is disabled and portions of a billboards behind terrain
    # be clipped. <br/><br/> This setting only applies when a billboard's {@link
    # Billboard#disableDepthTestDistance } value would otherwise allow depth testing—i.e.,
    # distance from the camera to the billboard is less than a billboard's {@link
    # Billboard#disableDepthTestDistance } value. Type: number.
    three_point_depth_test_distance: rx.Var[float]


