class BufferPolylineCollection(ResiumComponent):
    """Wraps resium ``BufferPolylineCollection``.

    BufferPolylineCollection is a high-performance collection of buffer polyline
    primitives (experimental). It can have BufferPolyline components as children.

    Scope:
      Inside Viewer or CesiumWidget component.
      A BufferPolylineCollection object will be attached to the PrimitiveCollection of the Viewer or CesiumWidget.

    Docs: https://resium.reearth.io/components/BufferPolylineCollection
    """

    tag = "BufferPolylineCollection"

    # Determines if primitives in this collection will be shown. Type: boolean.
    show: rx.Var[bool]

    # This property is for debugging only; it is not for production use nor is it optimized. <p>
    # Draws the bounding sphere for each draw command in the primitive. </p> Type: boolean.
    debug_show_bounding_volume: rx.Var[bool]

    # The maximum number of polylines this collection can hold. Fixed at creation time. Type:
    # number. Read-only: changing it re-creates the Cesium element.
    primitive_count_max: rx.Var[float]

    # The maximum number of vertices across all polylines in this collection. Fixed at creation
    # time. Type: number. Read-only: changing it re-creates the Cesium element.
    vertex_count_max: rx.Var[float]

    # Model-to-world transform applied to every polyline. Fixed at creation time — Cesium 1.141
    # made the property readonly post-construction. To animate, hold a ref and mutate the Matrix4
    # in place via `Matrix4.clone(next, current)`. Type: Matrix4. Read-only: changing it re-
    # creates the Cesium element.
