    # `modelMatrix` to the bounding volume that you apply to the polylines. Fixed at creation
    # time. Type: BoundingSphere. Read-only: changing it re-creates the Cesium element.
    bounding_volume: rx.Var[Any]

    # Blending mode for the collection. Pair with an alpha-aware `BufferPrimitiveMaterial` to
    # render translucent polylines. Fixed at creation time. Type: BlendOption. Read-only: changing
    # it re-creates the Cesium element.
    blend_option: rx.Var[float]

    # When set to a clamping value, the whole collection is draped onto terrain and/or 3D Tiles
    # (Cesium 1.145+) instead of being drawn as geometry of its own. `CLAMP_TO_TERRAIN` drapes
    # onto terrain, `CLAMP_TO_3D_TILE` onto 3D Tiles, and `CLAMP_TO_GROUND` onto both. Fixed at
    # creation time. Type: HeightReference. Read-only: changing it re-creates the Cesium element.
    height_reference: rx.Var[float]

    # Unit for `BufferPolyline` widths in this collection (Cesium 1.145+): `"pixels"` on screen
    # (the default), or `"meters"` in world space. Under a clamped `heightReference` those meters
    # are measured on the ellipsoid surface, so elevation and terrain slope stretch the drawn
    # width. Fixed at creation time. Type: "pixels" | "meters". Read-only: changing it re-creates
    # the Cesium element.
    width_units: rx.Var[str]

    _resium_readonly_props = ('primitive_count_max', 'vertex_count_max', 'model_matrix', 'bounding_volume', 'blend_option', 'height_reference', 'width_units')


