    # Type: DataSourceCollection. Read-only: changing it re-creates the Cesium element.
    data_sources: rx.Var[Any]

    # Type: Clock. Read-only: changing it re-creates the Cesium element.
    clock: rx.Var[Any]

    # Type: boolean. Read-only: changing it re-creates the Cesium element.
