    on_wheel: rx.EventHandler[wheel_event]

    # onUpdate()
    on_update: rx.EventHandler[no_args_event]

    _resium_readonly_props = ('shadows', 'ellipsoid', 'credit_container', 'credit_viewport', 'data_sources', 'clock', 'should_animate', 'base_layer', 'terrain', 'sky_box', 'sky_atmosphere', 'scene_mode', 'scene_3d_only', 'order_independent_translucency', 'map_projection', 'globe', 'show_render_loop_errors', 'automatically_track_data_source_clocks', 'context_options', 'terrain_shadows', 'map_mode_2d', 'blur_active_element_on_canvas_focus', 'request_render_mode', 'maximum_render_time_change', 'msaa_samples')

    _resium_renamed_props = {'scene_3d_only': 'scene3DOnly', 'map_mode_2d': 'mapMode2D'}

    @classmethod
    def create(cls, *children: Any, **props: Any) -> rx.Component:
        """Create the widget; children get the entity/data source context.

        resium's CesiumWidget does not provide Cesium's ``entities`` and
        ``dataSources`` collections, so children are wrapped with
        :class:`~reflex_resium.bridge.CesiumWidgetContext`.
        """
        from .bridge import CesiumWidgetContext

        return super().create(CesiumWidgetContext.create(*children), **props)


