class Clock(ResiumComponent):
    """Wraps resium ``Clock``.

    Clock can operate the clock of the Viewer or CesiumWidget. All properties are
    applied to single clock.

    Scope:
      Clock can be mounted insideViewer or CesiumWidget components.
      Clock can not be mounted more than once for each Viewer or CesiumWidget.

    Docs: https://resium.reearth.io/components/Clock
    """

    tag = "Clock"

    # Indicates whether {@link Clock#tick } should attempt to advance time. The clock will only
    # advance time when both {@link Clock#canAnimate } and {@link Clock#shouldAnimate } are true.
    # Changing this property will change {@link Clock#clockStep } from {@link
    # ClockStep.SYSTEM_CLOCK} to {@link ClockStep.SYSTEM_CLOCK_MULTIPLIER}. Type: boolean.
    should_animate: rx.Var[bool]

    # Indicates whether {@link Clock#tick } can advance time. This could be false if data is being
    # buffered, for example. The clock will only advance time when both {@link Clock#canAnimate }
    # and {@link Clock#shouldAnimate } are true. Type: boolean.
    can_animate: rx.Var[bool]

    # Determines how the clock should behave when {@link Clock#startTime } or {@link
    # Clock#stopTime } is reached. Type: ClockRange.
    clock_range: rx.Var[float]

    # Determines if calls to {@link Clock#tick } are frame dependent or system clock dependent.
    # Changing this property to {@link ClockStep.SYSTEM_CLOCK} will set {@link Clock#multiplier }
    # to 1.0, {@link Clock#shouldAnimate } to true, and {@link Clock#currentTime } to the current
    # system clock time. Type: ClockStep.
    clock_step: rx.Var[float]

    # The current time. Changing this property will change {@link Clock#clockStep } from {@link
    # ClockStep.SYSTEM_CLOCK} to {@link ClockStep.SYSTEM_CLOCK_MULTIPLIER}. Type: JulianDate.
    current_time: rx.Var[Any]

    # Gets or sets how much time advances when {@link Clock#tick } is called. Negative values
    # allow for advancing backwards. If {@link Clock#clockStep } is set to {@link
    # ClockStep.TICK_DEPENDENT}, this is the number of seconds to advance. If {@link
    # Clock#clockStep } is set to {@link ClockStep.SYSTEM_CLOCK_MULTIPLIER}, this value is
    # multiplied by the elapsed system time since the last call to {@link Clock#tick }. Changing
    # this property will change {@link Clock#clockStep } from {@link ClockStep.SYSTEM_CLOCK} to
    # {@link ClockStep.SYSTEM_CLOCK_MULTIPLIER}. Type: number.
    multiplier: rx.Var[float]

    # The start time of the clock. Type: JulianDate.
    start_time: rx.Var[Any]

    # The stop time of the clock. Type: JulianDate.
    stop_time: rx.Var[Any]

    # onStop(clock: Clock)
    on_stop: rx.EventHandler[clock_event]

    # onTick(clock: Clock)
    on_tick: rx.EventHandler[clock_event]


clock = Clock.create


class CloudCollection(ResiumComponent):
    """Wraps resium ``CloudCollection``.

    CloudCollection is a collection of cloud primitives. It can have some CumulusCloud
    components as children.

    Scope:
      Inside Viewer or CesiumWidget component.
      A CloudCollection object will be attached to the PrimitiveCollection of the Viewer or CesiumWidget.

    Docs: https://resium.reearth.io/components/CloudCollection
    """

    tag = "CloudCollection"

    # Determines if billboards in this collection will be shown. Type: boolean.
    show: rx.Var[bool]

    # <p> Controls the amount of detail captured in the precomputed noise texture used to render
    # the cumulus clouds. In order for the texture to be tileable, this must be a power of two.
    # For best results, set this to be a power of two between <code>8.0</code> and
    # <code>32.0</code> (inclusive). </p> <div align='center'> <table border='0'
    # cellpadding='5'><tr> <td align='center'> <code>clouds.noiseDetail = 8.0;</code><br/> <img
    # src='Images/CloudCollection.noiseDetail8.png' width='250' height='158' /> </td> <td
    # align='center'> <code>clouds.noiseDetail = 32.0;</code><br/> <img
    # src='Images/CloudCollection.noiseDetail32.png' width='250' height='158' /> </td>
    # </tr></table> </div> Type: number.
    noise_detail: rx.Var[float]

    # <p> Applies a translation to noise texture coordinates to generate different data. This can
    # be modified if the default noise does not generate good-looking clouds. </p> <div
    # align='center'> <table border='0' cellpadding='5'><tr> <td align='center'>
    # <code>default</code><br/> <img src='Images/CloudCollection.noiseOffsetdefault.png'
    # width='250' height='158' /> </td> <td align='center'> <code>clouds.noiseOffset = new
    # Cesium.Cartesian3(10, 20, 10);</code><br/> <img
    # src='Images/CloudCollection.noiseOffsetx10y20z10.png' width='250' height='158' /> </td>
    # </tr></table> </div> Type: Cartesian3.
    noise_offset: rx.Var[Any]

    # This property is for debugging only; it is not for production use nor is it optimized. <p>
    # Renders the billboards with one opaque color for the sake of debugging. </p> Type: boolean.
    debug_billboards: rx.Var[bool]

    # This property is for debugging only; it is not for production use nor is it optimized. <p>
    # Draws the clouds as opaque, monochrome ellipsoids for the sake of debugging. If
    # <code>debugBillboards</code> is also true, then the ellipsoids will draw on top of the
    # billboards. </p> Type: boolean.
    debug_ellipsoids: rx.Var[bool]


cloud_collection = CloudCollection.create


