class Fog(ResiumComponent):
    """Wraps resium ``Fog``.

    Fog can operate the fog of the scene. All properties are applied to single fog of
    the scene.

    Scope:
      Fog can be mounted insideViewer or CesiumWidget components.
      It can not be mounted more than once for each Viewer or CesiumWidget.

    Docs: https://resium.reearth.io/components/Fog
    """

    tag = "Fog"

    # A scalar that determines the density of the fog. Terrain that is in full fog are culled. The
    # density of the fog increases as this number approaches 1.0 and becomes less dense as it
    # approaches zero. The more dense the fog is, the more aggressively the terrain is culled. For
    # example, if the camera is a height of 1000.0m above the ellipsoid, increasing the value to
    # 3.0e-3 will cause many tiles close to the viewer be culled. Decreasing the value will push
    # the fog further from the viewer, but decrease performance as more of the terrain is
    # rendered. Type: number.
    density: rx.Var[float]

    # <code>true</code> if fog is enabled, <code>false</code> otherwise. Type: boolean.
    enabled: rx.Var[bool]

    # Exponent factor used in the function to adjust how density changes based on the height of
    # the camera above the ellipsoid. Smaller values produce a more gradual transition as camera
    # height increases. Value must be greater than 0. Type: number.
    height_falloff: rx.Var[float]

    # A scalar used in the function to adjust density based on the height of the camera above the
    # terrain. Type: number.
    height_scalar: rx.Var[float]

    # The maximum height fog is applied. If the camera is above this height fog will be disabled.
    # Type: number.
    max_height: rx.Var[float]

    # The minimum brightness of the fog color from lighting. A value of 0.0 can cause the fog to
    # be completely black. A value of 1.0 will not affect the brightness at all. Type: number.
    minimum_brightness: rx.Var[float]

    # <code>true</code> if fog is renderable in shaders, <code>false</code> otherwise. This allows
    # to benefits from optimized tile loading strategy based on fog density without the actual
    # visual rendering. Type: boolean.
    renderable: rx.Var[bool]

    # A factor used to increase the screen space error of terrain tiles when they are partially in
    # fog. The effect is to reduce the number of terrain tiles requested for rendering. If set to
    # zero, the feature will be disabled. If the value is increased for mountainous regions, less
    # tiles will need to be requested, but the terrain meshes near the horizon may be a noticeably
    # lower resolution. If the value is increased in a relatively flat area, there will be little
    # noticeable change on the horizon. Type: number.
    screen_space_error_factor: rx.Var[float]

    # A scalar that impacts the visual density of fog. This value does not impact the culling of
    # terrain. Use in combination with the {@link Fog.density} to make fog appear more or less
    # dense. Type: number.
    visual_density_scalar: rx.Var[float]


fog = Fog.create


