class GeoJsonPrimitive(ResiumComponent):
    """Wraps resium ``GeoJsonPrimitive``.

    GeoJsonPrimitive is a high-throughput companion to GeoJsonDataSource that loads
    GeoJSON directly into BufferPointCollection/BufferPolylineCollection/
    BufferPolygonCollection, bypassing the entity/DataSource layer.

    Scope:
      Inside Viewer or CesiumWidget component.
      A GeoJsonPrimitive object will be attached to the PrimitiveCollection of the Viewer or CesiumWidget.

    Docs: https://resium.reearth.io/components/GeoJsonPrimitive
    """

    tag = "GeoJsonPrimitive"

    # Type: boolean.
    show: rx.Var[bool]

    # Ellipsoid used to project GeoJSON coordinates. Fixed at creation time. Type: Ellipsoid.
    # Read-only: changing it re-creates the Cesium element.
    ellipsoid: rx.Var[Any]

    # Whether features in the primitive can be picked. Fixed at creation time. Type: boolean.
    # Read-only: changing it re-creates the Cesium element.
    allow_picking: rx.Var[bool]

    # Factory invoked to build the picked-object payload. Fixed at creation time. Type:
    # ((...params: any[]) => any). Read-only: changing it re-creates the Cesium element.
    pick_object_factory: rx.Var[Any]

    # Drapes the loaded GeoJSON onto terrain and/or 3D Tiles (Cesium 1.145+). `CLAMP_TO_TERRAIN`
    # drapes onto terrain, `CLAMP_TO_3D_TILE` onto 3D Tiles, and `CLAMP_TO_GROUND` onto both.
    # Cesium requires a `Scene` for clamping values; resium supplies the enclosing
    # `Viewer`/`CesiumWidget` scene automatically. Fixed at creation time. **Polylines and
    # polygons only.** As of Cesium 1.145 `GeoJsonPrimitive` does not support clamped points: it
    # builds its `BufferPointCollection` without a `heightReference` and never routes points
    # through the scene's vector provider, so `Point`/`MultiPoint` features keep their original
    # heights. A FeatureCollection carrying points plus a clamping value also makes Cesium log a
    # one-time `"Clamped HeightReference unsupported on BufferPointCollection"` warning. Type:
    # HeightReference. Read-only: changing it re-creates the Cesium element.
    height_reference: rx.Var[float]

    # Opt in to React Suspense for async loading. When enabled and the data is a URL or Resource,
    # it is fetched during render so a parent `<Suspense>` boundary can show a fallback and a
    # parent error boundary can catch failures. Type: boolean.
    suspense: rx.Var[bool]

    # Overrides the Suspense cache key (defaults to the resolved URL). Change it to bust the cache
    # when the content at a stable URL changes, or share it across components to dedupe a fetch.
    # Only used when `suspense` is enabled. Type: string.
    cache_key: rx.Var[str]

    # URL to fetch GeoJSON from. Mutually exclusive with `data` — if both are set, `url` wins.
    # Type: string | Resource.
    url: rx.Var[Any]

    # Inline GeoJSON FeatureCollection. Mutually exclusive with `url`. Type: object.
    data: rx.Var[Any]

    # onClick(movement: CesiumMovementEvent, target: unknown)
    on_click: rx.EventHandler[movement_event]

    # onDoubleClick(movement: CesiumMovementEvent, target: unknown)
    on_double_click: rx.EventHandler[movement_event]

    # onMouseDown(movement: CesiumMovementEvent, target: unknown)
    on_mouse_down: rx.EventHandler[movement_event]

    # onMouseUp(movement: CesiumMovementEvent, target: unknown)
    on_mouse_up: rx.EventHandler[movement_event]

    # onMiddleClick(movement: CesiumMovementEvent, target: unknown)
    on_middle_click: rx.EventHandler[movement_event]

    # onMiddleDown(movement: CesiumMovementEvent, target: unknown)
    on_middle_down: rx.EventHandler[movement_event]

    # onMiddleUp(movement: CesiumMovementEvent, target: unknown)
    on_middle_up: rx.EventHandler[movement_event]

    # onMouseMove(movement: CesiumMovementEvent, target: unknown)
    on_mouse_move: rx.EventHandler[movement_event]

    # onPinchEnd(movement: CesiumMovementEvent, target: unknown)
    on_pinch_end: rx.EventHandler[movement_event]

    # onPinchMove(movement: CesiumMovementEvent, target: unknown)
    on_pinch_move: rx.EventHandler[movement_event]

    # onPinchStart(movement: CesiumMovementEvent, target: unknown)
    on_pinch_start: rx.EventHandler[movement_event]

    # onRightClick(movement: CesiumMovementEvent, target: unknown)
    on_right_click: rx.EventHandler[movement_event]

    # onRightDown(movement: CesiumMovementEvent, target: unknown)
    on_right_down: rx.EventHandler[movement_event]

    # onRightUp(movement: CesiumMovementEvent, target: unknown)
    on_right_up: rx.EventHandler[movement_event]

    # onMouseEnter(movement: CesiumMovementEvent, target: unknown)
    on_mouse_enter: rx.EventHandler[movement_event]

    # onMouseLeave(movement: CesiumMovementEvent, target: unknown)
    on_mouse_leave: rx.EventHandler[movement_event]

    # onReady(primitive: GeoJsonPrimitiveShape) — Fires once the primitive is constructed, before
    # it is attached to the scene's primitive collection.
    on_ready: rx.EventHandler[object_event]

    # onError(err: unknown) — Fires if `fromUrl` rejects or the inline GeoJSON fails to parse.
    on_error: rx.EventHandler[error_event]

    _resium_readonly_props = ('ellipsoid', 'allow_picking', 'pick_object_factory', 'height_reference')


