class Globe(ResiumComponent):
    """Wraps resium ``Globe``.

    Globe can operate the globe of the scene. All properties are applied to single globe
    of the scene.

    Scope:
      Globe can be mounted insideViewer or CesiumWidget components.
      It can not be mounted more than once for each Viewer or CesiumWidget.

    Docs: https://resium.reearth.io/components/Globe
    """

    tag = "Globe"

    # Determines if the globe will be shown. Type: boolean.
    show: rx.Var[bool]

    # Gets or sets the material appearance of the Globe. This can be one of several built-in
    # {@link Material} objects or a custom material, scripted with {@link
    # https://github.com/CesiumGS/cesium/wiki/Fabric Fabric}. Type: Material.
    material: rx.Var[Any]

    # Determines whether the globe casts or receives shadows from light sources. Setting the globe
    # to cast shadows may impact performance since the terrain is rendered again from the light's
    # perspective. Currently only terrain that is in view casts shadows. By default the globe does
    # not cast shadows. Type: ShadowMode.
    shadows: rx.Var[float]

    # The maximum screen-space error used to drive level-of-detail refinement. Higher values will
    # provide better performance but lower visual quality. Type: number.
    maximum_screen_space_error: rx.Var[float]

    # A property specifying a {@link ClippingPlaneCollection} used to selectively disable
    # rendering on the outside of each plane. Type: ClippingPlaneCollection.
    clipping_planes: rx.Var[Any]

    # A property specifying a {@link ClippingPolygonCollection} used to selectively disable
    # rendering inside or outside a list of polygons. Type: ClippingPolygonCollection.
    clipping_polygons: rx.Var[Any]

    # Whether to cull back-facing terrain. Back faces are not culled when the camera is
    # underground or translucency is enabled. Type: boolean.
    back_face_culling: rx.Var[bool]

    # The brightness shift to apply to the atmosphere. Defaults to 0.0 (no shift). A brightness
    # shift of -1.0 is complete darkness, which will let space show through. Type: number.
    atmosphere_brightness_shift: rx.Var[float]

    # The hue shift to apply to the atmosphere. Defaults to 0.0 (no shift). A hue shift of 1.0
    # indicates a complete rotation of the hues available. Type: number.
    atmosphere_hue_shift: rx.Var[float]

    # The saturation shift to apply to the atmosphere. Defaults to 0.0 (no shift). A saturation
    # shift of -1.0 is monochrome. Type: number.
    atmosphere_saturation_shift: rx.Var[float]

    # Gets or sets the color of the globe when no imagery is available. Type: Color.
    base_color: rx.Var[Any]

    # True if primitives such as billboards, polylines, labels, etc. should be depth-tested
    # against the terrain surface, or false if such primitives should always be drawn on top of
    # terrain unless they're on the opposite side of the globe. The disadvantage of depth testing
    # primitives against terrain is that slight numerical noise or terrain level-of-detail
    # switched can sometimes make a primitive that should be on the surface disappear underneath
    # it. Type: boolean.
    depth_test_against_terrain: rx.Var[bool]

    # Enable lighting the globe with the scene's light source. Type: boolean.
    enable_lighting: rx.Var[bool]

    # The distance where lighting resumes. This only takes effect when <code>enableLighting</code>
    # or <code>showGroundAtmosphere</code> is <code>true</code>. Type: number.
    lighting_fade_in_distance: rx.Var[float]

    # The distance where everything becomes lit. This only takes effect when
    # <code>enableLighting</code> or <code>showGroundAtmosphere</code> is <code>true</code>. Type:
    # number.
    lighting_fade_out_distance: rx.Var[float]

    # The distance where the darkness of night from the ground atmosphere fades in to an unlit
    # ground atmosphere. This only takes effect when <code>showGroundAtmosphere</code>,
    # <code>enableLighting</code>, and <code>dynamicAtmosphereLighting</code> are
    # <code>true</code>. Type: number.
    night_fade_in_distance: rx.Var[float]

    # The distance where the darkness of night from the ground atmosphere fades out to a lit
    # ground atmosphere. This only takes effect when <code>showGroundAtmosphere</code>,
    # <code>enableLighting</code>, and <code>dynamicAtmosphereLighting</code> are
    # <code>true</code>. Type: number.
    night_fade_out_distance: rx.Var[float]

    # The normal map to use for rendering waves in the ocean. Setting this property will only have
    # an effect if the configured terrain provider includes a water mask. Type: string.
    ocean_normal_map_url: rx.Var[str]

    # Enable the ground atmosphere, which is drawn over the globe when viewed from a distance
    # between <code>lightingFadeInDistance</code> and <code>lightingFadeOutDistance</code>. Type:
    # boolean.
    show_ground_atmosphere: rx.Var[bool]

    # True if an animated wave effect should be shown in areas of the globe covered by water;
    # otherwise, false. This property is ignored if the <code>terrainProvider</code> does not
    # provide a water mask. Type: boolean.
    show_water_effect: rx.Var[bool]

    # The size of the terrain tile cache, expressed as a number of tiles. Any additional tiles
    # beyond this number will be freed, as long as they aren't needed for rendering this frame. A
    # larger number will consume more memory but will show detail faster when, for example,
    # zooming out and then back in. Type: number.
    tile_cache_size: rx.Var[float]

    # Gets or sets the number of loading descendant tiles that is considered "too many". If a tile
    # has too many loading descendants, that tile will be loaded and rendered before any of its
    # descendants are loaded and rendered. This means more feedback for the user that something is
    # happening at the cost of a longer overall load time. Setting this to 0 will cause each tile
    # level to be loaded successively, significantly increasing load time. Setting it to a large
    # number (e.g. 1000) will minimize the number of tiles that are loaded but tend to make detail
    # appear all at once after a long wait. Type: number.
    loading_descendant_limit: rx.Var[float]

    # Gets or sets a value indicating whether the ancestors of rendered tiles should be preloaded.
    # Setting this to true optimizes the zoom-out experience and provides more detail in newly-
    # exposed areas when panning. The down side is that it requires loading more tiles. Type:
    # boolean.
    preload_ancestors: rx.Var[bool]

    # Gets or sets a value indicating whether the siblings of rendered tiles should be preloaded.
    # Setting this to true causes tiles with the same parent as a rendered tile to be loaded, even
    # if they are culled. Setting this to true may provide a better panning experience at the cost
    # of loading more tiles. Type: boolean.
    preload_siblings: rx.Var[bool]

    # The color to use to highlight terrain fill tiles. If undefined, fill tiles are not
    # highlighted at all. The alpha value is used to alpha blend with the tile's actual color.
    # Because terrain fill tiles do not represent the actual terrain surface, it may be useful in
    # some applications to indicate visually that they are not to be trusted. Type: Color.
    fill_highlight_color: rx.Var[Any]

    # Enable dynamic lighting effects on atmosphere and fog. This only takes effect when
    # <code>enableLighting</code> is <code>true</code>. Type: boolean.
    dynamic_atmosphere_lighting: rx.Var[bool]

    # Whether dynamic atmosphere lighting uses the sun direction instead of the scene's light
    # direction. This only takes effect when <code>enableLighting</code> and
    # <code>dynamicAtmosphereLighting</code> are <code>true</code>. Type: boolean.
    dynamic_atmosphere_lighting_from_sun: rx.Var[bool]

    # Whether to show terrain skirts. Terrain skirts are geometry extending downwards from a
    # tile's edges used to hide seams between neighboring tiles. Skirts are always hidden when the
    # camera is underground or translucency is enabled. Type: boolean.
    show_skirts: rx.Var[bool]

    # A property specifying a {@link Rectangle} used to limit globe rendering to a cartographic
    # area. Defaults to the maximum extent of cartographic coordinates. Type: Rectangle.
    cartographic_limit_rectangle: rx.Var[Any]

    # Properties for controlling globe translucency. Type: GlobeTranslucency.
    translucency: rx.Var[Any]

    # The color to render the back side of the globe when the camera is underground or the globe
    # is translucent, blended with the globe color based on the camera's distance. <br /><br /> To
    # disable underground coloring, set <code>undergroundColor</code> to <code>undefined</code>.
    # Type: Color.
    underground_color: rx.Var[Any]

    # Gets or sets the near and far distance for blending {@link Globe#undergroundColor } with the
    # globe color. The alpha will interpolate between the {@link NearFarScalar#nearValue } and
    # {@link NearFarScalar#farValue } while the camera distance falls within the lower and upper
    # bounds of the specified {@link NearFarScalar#near } and {@link NearFarScalar#far }. Outside
    # of these ranges the alpha remains clamped to the nearest bound. If undefined, the
    # underground color will not be blended with the globe color. <br /> <br /> When the camera is
    # above the ellipsoid the distance is computed from the nearest point on the ellipsoid instead
    # of the camera's position. Type: NearFarScalar.
    underground_color_alpha_by_distance: rx.Var[Any]

    # A multiplier to adjust terrain lambert lighting. This number is multiplied by the result of
    # <code>czm_getLambertDiffuse</code> in GlobeFS.glsl. This only takes effect when
    # <code>enableLighting</code> is <code>true</code>. Type: number.
    lambert_diffuse_multiplier: rx.Var[float]

    # The intensity of the light that is used for computing the ground atmosphere color. Type:
    # number.
    atmosphere_light_intensity: rx.Var[float]

    # The Rayleigh scattering coefficient used in the atmospheric scattering equations for the
    # ground atmosphere. Type: Cartesian3.
    atmosphere_rayleigh_coefficient: rx.Var[Any]

    # The Mie scattering coefficient used in the atmospheric scattering equations for the ground
    # atmosphere. Type: Cartesian3.
    atmosphere_mie_coefficient: rx.Var[Any]

    # The Rayleigh scale height used in the atmospheric scattering equations for the ground
    # atmosphere, in meters. Type: number.
    atmosphere_rayleigh_scale_height: rx.Var[float]

    # The Mie scale height used in the atmospheric scattering equations for the ground atmosphere,
    # in meters. Type: number.
    atmosphere_mie_scale_height: rx.Var[float]

    # The anisotropy of the medium to consider for Mie scattering. <p> Valid values are between
    # -1.0 and 1.0. </p> Type: number.
    atmosphere_mie_anisotropy: rx.Var[float]

    # Determines the darkness of the vertex shadow. This only takes effect when
    # <code>enableLighting</code> is <code>true</code>. Type: number.
    vertex_shadow_darkness: rx.Var[float]

    # Type: TerrainProvider | Promise<TerrainProvider>.
    terrain_provider: rx.Var[Any]

    # onImageryLayersUpdate()
    on_imagery_layers_update: rx.EventHandler[no_args_event]

    # onTerrainProviderChange(terrainProvider: TerrainProvider)
    on_terrain_provider_change: rx.EventHandler[object_event]

    # onTileLoadProgress(currentLoadQueueLength: number)
    on_tile_load_progress: rx.EventHandler[number_event]


globe = Globe.create


class Google2DImageryProvider(ResiumComponent):
    """Wraps resium ``Google2DImageryProvider``.

    Google2DImageryProvider provides 2D satellite imagery from Google Maps tile
    services.

    Scope:
      Inside ImageryLayer component.

    Docs: https://resium.reearth.io/components/Google2DImageryProvider
    """

    tag = "Google2DImageryProvider"

    # The map type of the Google map imagery. Valid options are satellite, terrain, and roadmap.
    # Type: "terrain" | "satellite" | "roadmap".
    map_type: rx.Var[str]

    # An IETF language tag that specifies the language used to display information on the tiles.
    # Type: string.
    language: rx.Var[str]

    # A Common Locale Data Repository region identifier (two uppercase letters) that represents
    # the physical location of the user. Type: string.
    region: rx.Var[str]

    # Returns a transparent overlay map with the specified layerType. Type: "layerRoadmap" |
    # "layerStreetview" | "layerTraffic".
    overlay_layer_type: rx.Var[str]

    # An array of JSON style objects that specify the appearance and detail level of map features.
    # Type: any.
    styles: rx.Var[Any]

    # The ellipsoid. If not specified, the default ellipsoid is used. Type: Ellipsoid.
    ellipsoid: rx.Var[Any]

    # The minimum level-of-detail supported by the imagery provider. Type: number.
    minimum_level: rx.Var[float]

    # The maximum level-of-detail supported by the imagery provider. Type: number.
    maximum_level: rx.Var[float]

    # The rectangle, in radians, covered by the image. Type: Rectangle.
    rectangle: rx.Var[Any]

    # A credit for the data source, which is displayed on the canvas. Type: string | Credit.
    credit: rx.Var[Any]

    # The Ion asset ID to load from Cesium Ion. Alternative to using mapType/key. Type: string.
    asset_id: rx.Var[str]

    # The access token for Cesium Ion. Only needed if assetId is provided and different from
    # default. Type: string.
    access_token: rx.Var[str]

    # onReady(imageryProvider: Google2DImageryProvider) — Calls when the imagery provider is
    # successfully created.
    on_ready: rx.EventHandler[object_event]


google_2d_imagery_provider = Google2DImageryProvider.create


class GooglePhotorealistic3DTileset(ResiumComponent):
    """Wraps resium ``GooglePhotorealistic3DTileset``.

    GooglePhotorealistic3DTileset provides Google Maps Photorealistic 3D Tiles.

    Scope:
      Inside Viewer or CesiumWidget component.
      A Cesium3DTileset object will be attached to the PrimitiveCollection of the Viewer or CesiumWidget.

    Docs: https://resium.reearth.io/components/GooglePhotorealistic3DTileset
    """

    tag = "GooglePhotorealistic3DTileset"

    # Determines if the tileset will be shown. Type: boolean.
    show: rx.Var[bool]

    # The {@link SplitDirection} to apply to this tileset. Type: SplitDirection.
    split_direction: rx.Var[float]

    # This property is for debugging only; it is not optimized for production use. <p> When true,
    # renders the bounding volume for each visible tile. The bounding volume is white if the tile
    # has a content bounding volume or is empty; otherwise, it is red. Tiles that don't meet the
    # screen space error and are still refining to their descendants are yellow. </p> Type:
    # boolean.
    debug_show_bounding_volume: rx.Var[bool]

    # A 4x4 transformation matrix that transforms the entire tileset. Type: Matrix4.
    model_matrix: rx.Var[Any]

    # The color to use when rendering outlines. Type: Color.
    outline_color: rx.Var[Any]

    # Determines whether the tileset casts or receives shadows from light sources. <p> Enabling
    # shadows has a performance impact. A tileset that casts shadows must be rendered twice, once
    # from the camera and again from the light's point of view. </p> <p> Shadows are rendered only
    # when {@link Viewer#shadows } is <code>true</code>. </p> Type: ShadowMode.
    shadows: rx.Var[float]

    # The maximum screen space error used to drive level of detail refinement. This value helps
    # determine when a tile refines to its descendants, and therefore plays a major role in
    # balancing performance with visual quality. <p> A tile's screen space error is roughly
    # equivalent to the number of pixels wide that would be drawn if a sphere with a radius equal
    # to the tile's <b>geometric error</b> were rendered at the tile's position. If this value
    # exceeds <code>maximumScreenSpaceError</code> the tile refines to its descendants. </p> <p>
    # Depending on the tileset, <code>maximumScreenSpaceError</code> may need to be tweaked to
    # achieve the right balance. Higher values provide better performance but lower visual
    # quality. </p> Type: number.
    maximum_screen_space_error: rx.Var[float]

    # Optimization option. Don't request tiles that will likely be unused when they come back
    # because of the camera's movement. This optimization only applies to stationary tilesets.
    # Type: boolean.
    cull_requests_while_moving: rx.Var[bool]

    # Optimization option. Multiplier used in culling requests while moving. Larger is more
    # aggressive culling, smaller less aggressive culling. Type: number.
    cull_requests_while_moving_multiplier: rx.Var[float]

    # Preload tiles when <code>tileset.show</code> is <code>false</code>. Loads tiles as if the
    # tileset is visible but does not render them. Type: boolean.
    preload_when_hidden: rx.Var[bool]

    # Optimization option. Fetch tiles at the camera's flight destination while the camera is in
    # flight. Type: boolean.
    preload_flight_destinations: rx.Var[bool]

    # Optimization option. Prefer loading of leaves first. Type: boolean.
    prefer_leaves: rx.Var[bool]

    # Optimization option. If between (0.0, 0.5], tiles at or above the screen space error for the
    # reduced screen resolution of <code>progressiveResolutionHeightFraction*screenHeight</code>
    # will be prioritized first. This can help get a quick layer of tiles down while full
    # resolution tiles continue to load. Type: number.
    progressive_resolution_height_fraction: rx.Var[float]

    # Optimization option. Prioritize loading tiles in the center of the screen by temporarily
    # raising the screen space error for tiles around the edge of the screen. Screen space error
    # returns to normal once all the tiles in the center of the screen as determined by the {@link
    # Cesium3DTileset#foveatedConeSize } are loaded. Type: boolean.
    foveated_screen_space_error: rx.Var[bool]

    # Optimization option. Used when {@link Cesium3DTileset#foveatedScreenSpaceError } is true to
    # control the cone size that determines which tiles are deferred. Tiles that are inside this
    # cone are loaded immediately. Tiles outside the cone are potentially deferred based on how
    # far outside the cone they are and {@link Cesium3DTileset#foveatedInterpolationCallback } and
    # {@link Cesium3DTileset#foveatedMinimumScreenSpaceErrorRelaxation }. Setting this to 0.0
    # means the cone will be the line formed by the camera position and its view direction.
    # Setting this to 1.0 means the cone encompasses the entire field of view of the camera,
    # essentially disabling the effect. Type: number.
    foveated_cone_size: rx.Var[float]

    # Optimization option. Used when {@link Cesium3DTileset#foveatedScreenSpaceError } is true to
    # control the starting screen space error relaxation for tiles outside the foveated cone. The
    # screen space error will be raised starting with this value up to {@link
    # Cesium3DTileset#maximumScreenSpaceError } based on the provided {@link
    # Cesium3DTileset#foveatedInterpolationCallback }. Type: number.
    foveated_minimum_screen_space_error_relaxation: rx.Var[float]

    # Gets or sets a callback to control how much to raise the screen space error for tiles
    # outside the foveated cone, interpolating between {@link
    # Cesium3DTileset#foveatedMinimumScreenSpaceErrorRelaxation } and {@link
    # Cesium3DTileset#maximumScreenSpaceError }. Type: foveatedInterpolationCallback.
    foveated_interpolation_callback: rx.Var[Any]

    # Optimization option. Used when {@link Cesium3DTileset#foveatedScreenSpaceError } is true to
    # control how long in seconds to wait after the camera stops moving before deferred tiles
    # start loading in. This time delay prevents requesting tiles around the edges of the screen
    # when the camera is moving. Setting this to 0.0 will immediately request all tiles in any
    # given view. Type: number.
    foveated_time_delay: rx.Var[float]

    # Optimization option. For street-level horizon views, use lower resolution tiles far from the
    # camera. This reduces the amount of data loaded and improves tileset loading time with a
    # slight drop in visual quality in the distance. <p> This optimization is strongest when the
    # camera is close to the ground plane of the tileset and looking at the horizon. Furthermore,
    # the results are more accurate for tightly fitting bounding volumes like box and region.
    # Type: boolean.
    dynamic_screen_space_error: rx.Var[bool]

    # Similar to {@link Fog#density }, this option controls the camera distance at which the
    # {@link Cesium3DTileset#dynamicScreenSpaceError } optimization applies. Larger values will
    # cause tiles closer to the camera to be affected. This value must be non-negative. <p> This
    # optimization works by rolling off the tile screen space error (SSE) with camera distance
    # like a bell curve. This has the effect of selecting lower resolution tiles far from the
    # camera. Near the camera, no adjustment is made. For tiles further away, the SSE is reduced
    # by up to {@link Cesium3DTileset#dynamicScreenSpaceErrorFactor } (measured in pixels of
    # error). </p> <p> Increasing the density makes the bell curve narrower so tiles closer to the
    # camera are affected. This is analagous to moving fog closer to the camera. </p> <p> When the
    # density is 0, the optimization will have no effect on the tileset. </p> Type: number.
    dynamic_screen_space_error_density: rx.Var[float]

    # A parameter that controls the intensity of the {@link
    # Cesium3DTileset#dynamicScreenSpaceError } optimization for tiles on the horizon. Larger
    # values cause lower resolution tiles to load, improving runtime performance at a slight
    # reduction of visual quality. The value must be non-negative. <p> More specifically, this
    # parameter represents the maximum adjustment to screen space error (SSE) in pixels for tiles
    # far away from the camera. See {@link Cesium3DTileset#dynamicScreenSpaceErrorDensity } for
    # more details about how this optimization works. </p> <p> When the SSE factor is set to 0,
    # the optimization will have no effect on the tileset. </p> Type: number.
    dynamic_screen_space_error_factor: rx.Var[float]

    # A ratio of the tileset's height that determines "street level" for the {@link
    # Cesium3DTileset#dynamicScreenSpaceError } optimization. When the camera is below this
    # height, the dynamic screen space error optimization will have the maximum effect, and it
    # will roll off above this value. Valid values are between 0.0 and 1.0. <p> Type: number.
    dynamic_screen_space_error_height_falloff: rx.Var[float]

    # Controls how edges from the {@link https://github.com/KhronosGroup/glTF/pull/2479
    # EXT_mesh_primitive_edge_visibility} glTF extension are rendered relative to surface
    # geometry. Tile content primitives that do not declare the extension are unaffected. Type:
    # EdgeDisplayMode.
    edge_display_mode: rx.Var[float]

    # Optimization option. Determines if level of detail skipping should be applied during the
    # traversal. <p> The common strategy for replacement-refinement traversal is to store all
    # levels of the tree in memory and require all children to be loaded before the parent can
    # refine. With this optimization levels of the tree can be skipped entirely and children can
    # be rendered alongside their parents. The tileset requires significantly less memory when
    # using this optimization. </p> Type: boolean.
    skip_level_of_detail: rx.Var[bool]

    # The screen space error that must be reached before skipping levels of detail. <p> Only used
    # when {@link Cesium3DTileset#skipLevelOfDetail } is <code>true</code>. </p> Type: number.
    base_screen_space_error: rx.Var[float]

    # Multiplier defining the minimum screen space error to skip. For example, if a tile has
    # screen space error of 100, no tiles will be loaded unless they are leaves or have a screen
    # space error <code><= 100 / skipScreenSpaceErrorFactor</code>. <p> Only used when {@link
    # Cesium3DTileset#skipLevelOfDetail } is <code>true</code>. </p> Type: number.
    skip_screen_space_error_factor: rx.Var[float]

    # Constant defining the minimum number of levels to skip when loading tiles. When it is 0, no
    # levels are skipped. For example, if a tile is level 1, no tiles will be loaded unless they
    # are at level greater than 2. <p> Only used when {@link Cesium3DTileset#skipLevelOfDetail }
    # is <code>true</code>. </p> Type: number.
    skip_levels: rx.Var[float]

    # When true, only tiles that meet the maximum screen space error will ever be downloaded.
    # Skipping factors are ignored and just the desired tiles are loaded. <p> Only used when
    # {@link Cesium3DTileset#skipLevelOfDetail } is <code>true</code>. </p> Type: boolean.
    immediately_load_desired_level_of_detail: rx.Var[bool]

    # Determines whether siblings of visible tiles are always downloaded during traversal. This
    # may be useful for ensuring that tiles are already available when the viewer turns
    # left/right. <p> Only used when {@link Cesium3DTileset#skipLevelOfDetail } is
    # <code>true</code>. </p> Type: boolean.
    load_siblings: rx.Var[bool]

    # The {@link ClippingPlaneCollection} used to selectively disable rendering the tileset. Type:
    # ClippingPlaneCollection.
    clipping_planes: rx.Var[Any]

    # The {@link ClippingPolygonCollection} used to selectively disable rendering the tileset.
    # Type: ClippingPolygonCollection.
    clipping_polygons: rx.Var[Any]

    # The light color when shading models. When <code>undefined</code> the scene's light color is
    # used instead. <p> For example, disabling additional light sources by setting
    # <code>tileset.imageBasedLighting.imageBasedLightingFactor = new Cartesian2(0.0, 0.0)</code>
    # will make the tileset much darker. Here, increasing the intensity of the light source will
    # make the tileset brighter. </p> Type: Cartesian3.
    light_color: rx.Var[Any]

    # Defines the value used to linearly interpolate between the source color and feature color
    # when the {@link Cesium3DTileset#colorBlendMode } is <code>MIX</code>. A value of 0.0 results
    # in the source color while a value of 1.0 results in the feature color, with any value in-
    # between resulting in a mix of the source color and feature color. Type: number.
    color_blend_amount: rx.Var[float]

    # Defines how per-feature colors set from the Cesium API or declarative styling blend with the
    # source colors from the original feature, e.g. glTF material or per-point color in the tile.
    # Type: Cesium3DTileColorBlendMode.
    color_blend_mode: rx.Var[float]

    # This property is for debugging only; it is not optimized for production use. <p> Determines
    # if only the tiles from last frame should be used for rendering. This effectively "freezes"
    # the tileset to the previous frame so it is possible to zoom out and see what was rendered.
    # </p> Type: boolean.
    debug_freeze_frame: rx.Var[bool]

    # This property is for debugging only; it is not optimized for production use. <p> When true,
    # assigns a random color to each tile. This is useful for visualizing what features belong to
    # what tiles, especially with additive refinement where features from parent tiles may be
    # interleaved with features from child tiles. </p> Type: boolean.
    debug_colorize_tiles: rx.Var[bool]

    # This property is for debugging only; it is not optimized for production use. <p> When true,
    # renders each tile's content as a wireframe. </p> Type: boolean.
    debug_wireframe: rx.Var[bool]

    # This property is for debugging only; it is not optimized for production use. <p> When true,
    # renders the bounding volume for each visible tile's content. The bounding volume is blue if
    # the tile has a content bounding volume; otherwise it is red. </p> Type: boolean.
    debug_show_content_bounding_volume: rx.Var[bool]

    # This property is for debugging only; it is not optimized for production use. <p> When true,
    # renders the viewer request volume for each tile. </p> Type: boolean.
    debug_show_viewer_request_volume: rx.Var[bool]

    # This property is for debugging only; it is not optimized for production use. <p> When true,
    # draws labels to indicate the geometric error of each tile. </p> Type: boolean.
    debug_show_geometric_error: rx.Var[bool]

    # This property is for debugging only; it is not optimized for production use. <p> When true,
    # draws labels to indicate the number of commands, points, triangles and features of each
    # tile. </p> Type: boolean.
    debug_show_rendering_statistics: rx.Var[bool]

    # This property is for debugging only; it is not optimized for production use. <p> When true,
    # draws labels to indicate the geometry and texture memory usage of each tile. </p> Type:
    # boolean.
    debug_show_memory_usage: rx.Var[bool]

    # This property is for debugging only; it is not optimized for production use. <p> When true,
    # draws labels to indicate the url of each tile. </p> Type: boolean.
    debug_show_url: rx.Var[bool]

    # The style, defined using the {@link
    # https://github.com/CesiumGS/3d-tiles/tree/main/specification/Styling 3D Tiles Styling
    # language}, applied to each feature in the tileset. <p> Assign <code>undefined</code> to
    # remove the style, which will restore the visual appearance of the tileset to its default
    # when no style was applied. </p> <p> The style is applied to a tile before the {@link
    # Cesium3DTileset#tileVisible } event is raised, so code in <code>tileVisible</code> can
    # manually set a feature's properties (e.g. color and show) after the style is applied. When a
    # new style is assigned any manually set properties are overwritten. </p> <p> Use an always
    # "true" condition to specify the Color for all objects that are not overridden by pre-
    # existing conditions. Otherwise, the default color Cesium.Color.White will be used.
    # Similarly, use an always "true" condition to specify the show property for all objects that
    # are not overridden by pre-existing conditions. Otherwise, the default show value true will
    # be used. </p> Type: Cesium3DTileStyle.
    cesium_style: rx.Var[Any]

    # Whether to cull back-facing geometry. When true, back face culling is determined by the glTF
    # material's doubleSided property; when false, back face culling is disabled. Type: boolean.
    back_face_culling: rx.Var[bool]

    # Whether to display the outline for models using the {@link https://github.com/KhronosGroup/g
    # lTF/tree/master/extensions/2.0/Vendor/CESIUM_primitive_outline CESIUM_primitive_outline}
    # extension. When true, outlines are displayed. When false, outlines are not displayed. Type:
    # boolean.
    show_outline: rx.Var[bool]

    # Indicates that only the tileset's vector tiles should be used for classification. Type:
    # boolean.
    vector_classification_only: rx.Var[bool]

    # Whether vector tiles should keep decoded positions in memory. This is used with {@link
    # Cesium3DTileFeature.getPolylinePositions }. Type: boolean.
    vector_keep_decoded_positions: rx.Var[bool]

    # A custom shader to apply to all tiles in the tileset. Only used for contents that use {@link
    # Model}. Using custom shaders with a {@link Cesium3DTileStyle} may lead to undefined
    # behavior. Type: CustomShader.
    custom_shader: rx.Var[Any]

    # The properties for managing image-based lighting on this tileset. Type: ImageBasedLighting.
    image_based_lighting: rx.Var[Any]

    # Determines whether the credits of the tileset will be displayed on the screen Type: boolean.
    show_credits_on_screen: rx.Var[bool]

    # Label of the feature ID set to use for picking and styling. <p> For EXT_mesh_features, this
    # is the feature ID's label property, or "featureId_N" (where N is the index in the featureIds
    # array) when not specified. EXT_feature_metadata did not have a label field, so such feature
    # ID sets are always labeled "featureId_N" where N is the index in the list of all feature
    # Ids, where feature ID attributes are listed before feature ID textures. </p> <p> If
    # featureIdLabel is set to an integer N, it is converted to the string "featureId_N"
    # automatically. If both per-primitive and per-instance feature IDs are present, the instance
    # feature IDs take priority. </p> Type: string.
    feature_id_label: rx.Var[str]

    # Label of the instance feature ID set used for picking and styling. <p> If
    # instanceFeatureIdLabel is set to an integer N, it is converted to the string
    # "instanceFeatureId_N" automatically. If both per-primitive and per-instance feature IDs are
    # present, the instance feature IDs take priority. </p> Type: string.
    instance_feature_id_label: rx.Var[str]

    # The amount of GPU memory (in bytes) used to cache tiles. This memory usage is estimated from
    # geometry, textures, and batch table textures of loaded tiles. For point clouds, this value
    # also includes per-point metadata. <p> Tiles not in view are unloaded to enforce this. </p>
    # <p> If decreasing this value results in unloading tiles, the tiles are unloaded the next
    # frame. </p> <p> If tiles sized more than <code>cacheBytes</code> are needed to meet the
    # desired screen space error, determined by {@link Cesium3DTileset#maximumScreenSpaceError },
    # for the current view, then the memory usage of the tiles loaded will exceed
    # <code>cacheBytes</code> by up to <code>maximumCacheOverflowBytes</code>. For example, if
    # <code>cacheBytes</code> is 500000, but 600000 bytes of tiles are needed to meet the screen
    # space error, then 600000 bytes of tiles may be loaded (if
    # <code>maximumCacheOverflowBytes</code> is at least 100000). When these tiles go out of view,
    # they will be unloaded. </p> Type: number.
    cache_bytes: rx.Var[float]

    # The maximum additional amount of GPU memory (in bytes) that will be used to cache tiles. <p>
    # If tiles sized more than <code>cacheBytes</code> plus <code>maximumCacheOverflowBytes</code>
    # are needed to meet the desired screen space error, determined by {@link
    # Cesium3DTileset#maximumScreenSpaceError } for the current view, then {@link
    # Cesium3DTileset#memoryAdjustedScreenSpaceError } will be adjusted until the tiles required
    # to meet the adjusted screen space error use less than <code>cacheBytes</code> plus
    # <code>maximumCacheOverflowBytes</code>. </p> Type: number.
    maximum_cache_overflow_bytes: rx.Var[float]

    # If <code>true</code>, allows collisions for camera collisions or picking. While this is
    # <code>true</code> the camera will be prevented from going in or below the tileset surface if
    # {@link ScreenSpaceCameraController#enableCollisionDetection } is true. This can have
    # performance implecations if the tileset contains tile with a larger number of vertices.
    # Type: boolean.
    enable_collision: rx.Var[bool]

    # Type: HeightReference. Read-only: changing it re-creates the Cesium element.
    height_reference: rx.Var[float]

    # Type: ClassificationType. Read-only: changing it re-creates the Cesium element.
    classification_type: rx.Var[float]

    # Type: Scene. Read-only: changing it re-creates the Cesium element.
    scene: rx.Var[Any]

