class HybridScreenSpacePanCameraController(ResiumComponent):
    """Wraps resium ``HybridScreenSpacePanCameraController``.

    HybridScreenSpacePanCameraController combines map panning and elevator panning, and
    switches between them based on how far the camera is looking from nadir. Looking
    mostly down pans across the map; looking towards the horizon pans vertically. It is
    one of the alternative camera controllers added in Cesium 1.144, built on the
    composable Controller framework.

    Scope:
      Inside Viewer or CesiumWidget components.
      The controller is registered with the scene's ControllerHost.

    Docs: https://resium.reearth.io/components/HybridScreenSpacePanCameraController
    """

    tag = "HybridScreenSpacePanCameraController"

    # Determines if the controller is enabled and should be updated by the host scene. Type:
    # boolean.
    enabled: rx.Var[bool]

    # The angle threshold in radians that determines which controller is used. If the camera is
    # looking within this angle of nadir, the map controller is used. Otherwise, the elevator
    # controller is used. Type: number.
    angle_threshold: rx.Var[float]

    # Precedence relative to other registered controllers. `0` applies before every other
    # controller; omitting it makes this controller the highest priority. Changing this prop re-
    # registers the controller. Type: number. Read-only: changing it re-creates the Cesium
    # element.
    priority: rx.Var[float]

    _resium_readonly_props = ('priority',)


hybrid_screen_space_pan_camera_controller = HybridScreenSpacePanCameraController.create


