class KmlDataSource(ResiumComponent):
    """Wraps resium ``KmlDataSource``.

    KmlDataSource provides the way to load and show KML data into the scene. Both KML
    and KMZ are supported, and can be loaded from a URL, string or raw object.

    Scope:
      Inside Viewer or CesiumWidget components.

    Docs: https://resium.reearth.io/components/KmlDataSource
    """

    tag = "KmlDataSource"

    # Gets whether or not this data source should be displayed. Type: boolean.
    show: rx.Var[bool]

    # Gets or sets the clustering options for this data source. This object can be shared between
    # multiple data sources. Type: EntityCluster.
    clustering: rx.Var[Any]

    # Gets or sets a human-readable name for this instance. This will be automatically be set to
    # the KML document name on load. Type: string.
    name: rx.Var[str]

    # Type: Ellipsoid. Read-only: changing it re-creates the Cesium element.
    ellipsoid: rx.Var[Any]

    # Gets the credit that will be displayed for the data source Type: Credit. Read-only: changing
    # it re-creates the Cesium element.
    credit: rx.Var[Any]

    # The current size of this Canvas will be used to populate the Link parameters for client
    # height and width. Type: HTMLCanvasElement. Read-only: changing it re-creates the Cesium
    # element.
    canvas: rx.Var[Any]

    # The position and orientation of this {@link Camera} will be used to populate various camera
    # parameters when making network requests. Camera movement will determine when to trigger
    # NetworkLink refresh if <code>viewRefreshMode</code> is <code>onStop</code>. Type: Camera.
    # Read-only: changing it re-creates the Cesium element.
    camera: rx.Var[Any]

    # Type: string. Read-only: changing it re-creates the Cesium element.
    source_uri: rx.Var[str]

    # Type: boolean. Read-only: changing it re-creates the Cesium element.
    clamp_to_ground: rx.Var[bool]

    # Type: string | Element. Read-only: changing it re-creates the Cesium element.
    screen_overlay_container: rx.Var[Any]

    # Opt in to React Suspense for async loading. When enabled and the data is a URL or Resource,
    # it is fetched during render so a parent `<Suspense>` boundary can show a fallback and a
    # parent error boundary can catch failures. Type: boolean.
    suspense: rx.Var[bool]

    # Overrides the Suspense cache key (defaults to the resolved URL). Change it to bust the cache
    # when the content at a stable URL changes, or share it across components to dedupe a fetch.
    # Only used when `suspense` is enabled. Type: string.
    cache_key: rx.Var[str]

    # Type: string | Resource | Document | Blob.
    data: rx.Var[Any]

    # onChange(kmlDataSource: KmlDataSource)
    on_change: rx.EventHandler[data_source_event]

    # onError(kmlDataSource: KmlDataSource, error: any)
    on_error: rx.EventHandler[data_source_error_event]

    # onLoading(kmlDataSource: KmlDataSource, isLoaded: boolean)
    on_loading: rx.EventHandler[data_source_loading_event]

    # onRefresh(kmlDataSource: KmlDataSource, urlComponent: string)
    on_refresh: rx.EventHandler[kml_refresh_event]

    # onUnsupportedNode(kmlDataSource: KmlDataSource)
