    # onClick(movement: CesiumMovementEvent, target: EventTarget)
    on_click: rx.EventHandler[movement_event]

    # onDoubleClick(movement: CesiumMovementEvent, target: EventTarget)
    on_double_click: rx.EventHandler[movement_event]

    # onMouseDown(movement: CesiumMovementEvent, target: EventTarget)
    on_mouse_down: rx.EventHandler[movement_event]

    # onMouseUp(movement: CesiumMovementEvent, target: EventTarget)
    on_mouse_up: rx.EventHandler[movement_event]

    # onMiddleClick(movement: CesiumMovementEvent, target: EventTarget)
    on_middle_click: rx.EventHandler[movement_event]

    # onMiddleDown(movement: CesiumMovementEvent, target: EventTarget)
    on_middle_down: rx.EventHandler[movement_event]

    # onMiddleUp(movement: CesiumMovementEvent, target: EventTarget)
    on_middle_up: rx.EventHandler[movement_event]

    # onMouseMove(movement: CesiumMovementEvent, target: EventTarget)
    on_mouse_move: rx.EventHandler[movement_event]

    # onPinchEnd(movement: CesiumMovementEvent, target: EventTarget)
    on_pinch_end: rx.EventHandler[movement_event]

    # onPinchMove(movement: CesiumMovementEvent, target: EventTarget)
    on_pinch_move: rx.EventHandler[movement_event]

