class Label(ResiumComponent):
    """Wraps resium ``Label``.

    Lavbel is a label primitive in the LabelCollection.

    Scope:
      Only inside LabelCollection component.
      A label object will be attached to the parent LabelCollection.

    Docs: https://resium.reearth.io/components/Label
    """

    tag = "Label"

    # Gets or sets the Cartesian position of this label. Type: Cartesian3. Required.
    position: rx.Var[Any]

    # Gets or sets the distance from the camera, beyond which, depth testing is disabled—to, for
    # example, prevent clipping against terrain. When set to <code>undefined</code> or
    # <code>0</code>, the depth test is always applied. When set to
    # Number.<code>POSITIVE_INFINITY</code>, the depth test is never applied. Type: number.
    disable_depth_test_distance: rx.Var[float]

    # Gets or sets the condition specifying at what distance from the camera that this label will
    # be displayed. Type: DistanceDisplayCondition.
    distance_display_condition: rx.Var[Any]

    # Gets and sets the 3D Cartesian offset applied to this label in eye coordinates. Eye
    # coordinates is a left-handed coordinate system, where <code>x</code> points towards the
    # viewer's right, <code>y</code> points up, and <code>z</code> points into the screen. Eye
    # coordinates use the same scale as world and model coordinates, which is typically meters.
    # <br /><br /> An eye offset is commonly used to arrange multiple label or objects at the same
    # position, e.g., to arrange a label above its corresponding 3D model. <br /><br /> Below, the
    # label is positioned at the center of the Earth but an eye offset makes it always appear on
    # top of the Earth regardless of the viewer's or Earth's orientation. <br /><br /> <div
    # align='center'> <table border='0' cellpadding='5'><tr> <td align='center'><img
    # src='Images/Billboard.setEyeOffset.one.png' width='250' height='188' /></td> <td
    # align='center'><img src='Images/Billboard.setEyeOffset.two.png' width='250' height='188'
    # /></td> </tr></table> <code>l.eyeOffset = new Cartesian3(0.0, 8000000.0, 0.0);</code><br
    # /><br /> </div> Type: Cartesian3.
    eye_offset: rx.Var[Any]

    # Gets or sets the height reference of this billboard. Type: HeightReference.
    height_reference: rx.Var[float]

    # Gets or sets the horizontal origin of this label, which determines if the label is drawn to
    # the left, center, or right of its anchor position. <br /><br /> <div align='center'> <img
    # src='Images/Billboard.setHorizontalOrigin.png' width='648' height='196' /><br /> </div>
    # Type: HorizontalOrigin.
    horizontal_origin: rx.Var[float]

    # Gets or sets the pixel offset in screen space from the origin of this label. This is
    # commonly used to align multiple labels and billboards at the same position, e.g., an image
    # and text. The screen space origin is the top, left corner of the canvas; <code>x</code>
    # increases from left to right, and <code>y</code> increases from top to bottom. <br /><br />
    # <div align='center'> <table border='0' cellpadding='5'><tr> <td
    # align='center'><code>default</code><br/><img src='Images/Label.setPixelOffset.default.png'
    # width='250' height='188' /></td> <td align='center'><code>l.pixeloffset = new Cartesian2(25,
    # 75);</code><br/><img src='Images/Label.setPixelOffset.x50y-25.png' width='250' height='188'
    # /></td> </tr></table> The label's origin is indicated by the yellow point. </div> Type:
    # Cartesian2.
    pixel_offset: rx.Var[Any]

    # Gets or sets near and far pixel offset scaling properties of a Label based on the Label's
    # distance from the camera. A label's pixel offset will be scaled between the {@link
    # NearFarScalar#nearValue } and {@link NearFarScalar#farValue } while the camera distance
    # falls within the lower and upper bounds of the specified {@link NearFarScalar#near } and
    # {@link NearFarScalar#far }. Outside of these ranges the label's pixel offset scaling remains
    # clamped to the nearest bound. If undefined, pixelOffsetScaleByDistance will be disabled.
    # Type: NearFarScalar.
    pixel_offset_scale_by_distance: rx.Var[Any]

    # Gets or sets the uniform scale that is multiplied with the label's size in pixels. A scale
    # of <code>1.0</code> does not change the size of the label; a scale greater than
    # <code>1.0</code> enlarges the label; a positive scale less than <code>1.0</code> shrinks the
    # label. <br /><br /> Applying a large scale value may pixelate the label. To make text larger
    # without pixelation, use a larger font size when calling {@link Label#font } instead. <br
    # /><br /> <div align='center'> <img src='Images/Label.setScale.png' width='400' height='300'
    # /><br/> From left to right in the above image, the scales are <code>0.5</code>,
    # <code>1.0</code>, and <code>2.0</code>. </div> Type: number.
    scale: rx.Var[float]

    # Gets or sets near and far scaling properties of a Label based on the label's distance from
    # the camera. A label's scale will interpolate between the {@link NearFarScalar#nearValue }
    # and {@link NearFarScalar#farValue } while the camera distance falls within the lower and
    # upper bounds of the specified {@link NearFarScalar#near } and {@link NearFarScalar#far }.
    # Outside of these ranges the label's scale remains clamped to the nearest bound. If
    # undefined, scaleByDistance will be disabled. Type: NearFarScalar.
    scale_by_distance: rx.Var[Any]

    # Determines if this label will be shown. Use this to hide or show a label, instead of
    # removing it and re-adding it to the collection. Type: boolean.
    show: rx.Var[bool]

    # Gets or sets near and far translucency properties of a Label based on the Label's distance
    # from the camera. A label's translucency will interpolate between the {@link
    # NearFarScalar#nearValue } and {@link NearFarScalar#farValue } while the camera distance
    # falls within the lower and upper bounds of the specified {@link NearFarScalar#near } and
    # {@link NearFarScalar#far }. Outside of these ranges the label's translucency remains clamped
    # to the nearest bound. If undefined, translucencyByDistance will be disabled. Type:
    # NearFarScalar.
    translucency_by_distance: rx.Var[Any]

    # Gets or sets the vertical origin of this label, which determines if the label is to the
    # above, below, or at the center of its anchor position. <br /><br /> <div align='center'>
    # <img src='Images/Billboard.setVerticalOrigin.png' width='695' height='175' /><br /> </div>
    # Type: VerticalOrigin.
    vertical_origin: rx.Var[float]

    # Gets or sets the outline color of this label. Type: Color.
    outline_color: rx.Var[Any]

    # Gets or sets the outline width of this label. Type: number.
    outline_width: rx.Var[float]

    # Gets or sets the style of this label. Type: LabelStyle.
    cesium_style: rx.Var[float]

    # Gets or sets the background color of this label. Type: Color.
    background_color: rx.Var[Any]

    # Gets or sets the background padding, in pixels, of this label. The <code>x</code> value
    # controls horizontal padding, and the <code>y</code> value controls vertical padding. Type:
    # Cartesian2.
    background_padding: rx.Var[Any]

    # Gets or sets the fill color of this label. Type: Color.
    fill_color: rx.Var[Any]

    # Gets or sets the font used to draw this label. Fonts are specified using the same syntax as
    # the CSS 'font' property. Type: string.
    font: rx.Var[str]

    # Determines if a background behind this label will be shown. Type: boolean.
    show_background: rx.Var[bool]

    # Gets or sets the text of this label. Type: string.
    text: rx.Var[str]

    # onClick(movement: CesiumMovementEvent, target: { collection: LabelCollection; primitive:
    # Label; })
    on_click: rx.EventHandler[movement_event]

    # onDoubleClick(movement: CesiumMovementEvent, target: { collection: LabelCollection;
    # primitive: Label; })
    on_double_click: rx.EventHandler[movement_event]

    # onMouseDown(movement: CesiumMovementEvent, target: { collection: LabelCollection; primitive:
    # Label; })
    on_mouse_down: rx.EventHandler[movement_event]

    # onMouseUp(movement: CesiumMovementEvent, target: { collection: LabelCollection; primitive:
    # Label; })
    on_mouse_up: rx.EventHandler[movement_event]

    # onMiddleClick(movement: CesiumMovementEvent, target: { collection: LabelCollection;
    # primitive: Label; })
    on_middle_click: rx.EventHandler[movement_event]

    # onMiddleDown(movement: CesiumMovementEvent, target: { collection: LabelCollection;
    # primitive: Label; })
    on_middle_down: rx.EventHandler[movement_event]

    # onMiddleUp(movement: CesiumMovementEvent, target: { collection: LabelCollection; primitive:
    # Label; })
    on_middle_up: rx.EventHandler[movement_event]

    # onMouseMove(movement: CesiumMovementEvent, target: { collection: LabelCollection; primitive:
    # Label; })
    on_mouse_move: rx.EventHandler[movement_event]

    # onPinchEnd(movement: CesiumMovementEvent, target: { collection: LabelCollection; primitive:
    # Label; })
    on_pinch_end: rx.EventHandler[movement_event]

    # onPinchMove(movement: CesiumMovementEvent, target: { collection: LabelCollection; primitive:
    # Label; })
    on_pinch_move: rx.EventHandler[movement_event]

    # onPinchStart(movement: CesiumMovementEvent, target: { collection: LabelCollection;
    # primitive: Label; })
    on_pinch_start: rx.EventHandler[movement_event]

    # onRightClick(movement: CesiumMovementEvent, target: { collection: LabelCollection;
    # primitive: Label; })
    on_right_click: rx.EventHandler[movement_event]

    # onRightDown(movement: CesiumMovementEvent, target: { collection: LabelCollection; primitive:
    # Label; })
    on_right_down: rx.EventHandler[movement_event]

    # onRightUp(movement: CesiumMovementEvent, target: { collection: LabelCollection; primitive:
    # Label; })
    on_right_up: rx.EventHandler[movement_event]

    # onMouseEnter(movement: CesiumMovementEvent, target: { collection: LabelCollection;
    # primitive: Label; })
    on_mouse_enter: rx.EventHandler[movement_event]

    # onMouseLeave(movement: CesiumMovementEvent, target: { collection: LabelCollection;
    # primitive: Label; })
    on_mouse_leave: rx.EventHandler[movement_event]

    _resium_renamed_props = {'cesium_style': 'style'}


label = Label.create


class LabelCollection(ResiumComponent):
    """Wraps resium ``LabelCollection``.

    LabelCollection is a collection of label primitives. It can have some Label
    components as children.

    Scope:
      Inside Viewer or CesiumWidget component.
      A LabelCollection object will be attached to the PrimitiveCollection of the Viewer or CesiumWidget.

    Docs: https://resium.reearth.io/components/LabelCollection
    """

    tag = "LabelCollection"

    # Determines if labels in this collection will be shown. Type: boolean.
    show: rx.Var[bool]

    # The label blending option. The default is used for rendering both opaque and translucent
    # labels. However, if either all of the labels are completely opaque or all are completely
    # translucent, setting the technique to BlendOption.OPAQUE or BlendOption.TRANSLUCENT can
    # improve performance by up to 2x. Type: BlendOption.
    blend_option: rx.Var[float]

    # The distance from the camera, beyond which, labels are depth-tested against an approximation
    # of the globe ellipsoid rather than against the full globe depth buffer. When set to
    # <code>0</code>, the approximate depth test is always applied. When set to
    # <code>Number.POSITIVE_INFINITY</code>, the approximate depth test is never applied.
    # <br/><br/> This setting only applies when a label's {@link Label#disableDepthTestDistance }
    # value would otherwise allow depth testing—i.e., distance from the camera to the label is
    # less than the label's {@link Label#disableDepthTestDistance } value. Type: number.
    coarse_depth_test_distance: rx.Var[float]

    # This property is for debugging only; it is not for production use nor is it optimized. <p>
    # Draws the bounding sphere for each draw command in the primitive. </p> Type: boolean.
    debug_show_bounding_volume: rx.Var[bool]

    # The 4x4 transformation matrix that transforms each label in this collection from model to
    # world coordinates. When this is the identity matrix, the labels are drawn in world
    # coordinates, i.e., Earth's WGS84 coordinates. Local reference frames can be used by
    # providing a different transformation matrix, like that returned by {@link
    # Transforms.eastNorthUpToFixedFrame}. Type: Matrix4.
    model_matrix: rx.Var[Any]

    # The distance from the camera, within which, labels with a {@link Label#heightReference }
    # value of {@link HeightReference.CLAMP_TO_GROUND} or {@link HeightReference.CLAMP_TO_TERRAIN}
    # are depth tested against three key points. This ensures that if any key point of the label
    # is visible, the whole label will be visible. When set to <code>0</code>, this feature is
    # disabled and portions of a label behind terrain be clipped. <br/><br/> This setting only
    # applies when a labels's {@link Label#disableDepthTestDistance } value would otherwise allow
    # depth testing—i.e., distance from the camera to the label is less than the labels's {@link
    # Label#disableDepthTestDistance } value. Type: number.
    three_point_depth_test_distance: rx.Var[float]


label_collection = LabelCollection.create


