class Model(ResiumComponent):
    """Wraps resium ``Model``.

    Resium Model component.

    Docs: https://resium.reearth.io/components/Model
    """

    tag = "Model"

    # The color to blend with the model's rendered color. Type: Color.
    color: rx.Var[Any]

    # Gets or sets the distance display condition, which specifies at what distance from the
    # camera this model will be displayed. Type: DistanceDisplayCondition.
    distance_display_condition: rx.Var[Any]

    # The height reference of the model, which determines how the model is drawn relative to
    # terrain. Type: HeightReference.
    height_reference: rx.Var[float]

    # A uniform scale applied to this model before the {@link Model#modelMatrix }. Values greater
    # than <code>1.0</code> increase the size of the model; values less than <code>1.0</code>
    # decrease. Type: number.
    scale: rx.Var[float]

    # Whether or not to render the model. Type: boolean.
    show: rx.Var[bool]

    # The {@link SplitDirection} to apply to this model. Type: SplitDirection.
    split_direction: rx.Var[float]

    # This property is for debugging only; it is not for production use nor is it optimized. <p>
    # Draws the bounding sphere for each draw command in the model. </p> Type: boolean.
    debug_show_bounding_volume: rx.Var[bool]

    # The 4x4 transformation matrix that transforms the model from model to world coordinates.
    # When this is the identity matrix, the model is drawn in world coordinates, i.e., Earth's
    # Cartesian WGS84 coordinates. Local reference frames can be used by providing a different
    # transformation matrix, like that returned by {@link Transforms.eastNorthUpToFixedFrame}.
    # Type: Matrix4.
    model_matrix: rx.Var[Any]

    # The color to use when rendering outlines. Type: Color.
    outline_color: rx.Var[Any]

    # Determines whether the model casts or receives shadows from light sources. Type: ShadowMode.
    shadows: rx.Var[float]

    # Controls how edges from the {@link https://github.com/KhronosGroup/glTF/pull/2479
    # EXT_mesh_primitive_edge_visibility} glTF extension are rendered relative to surface
    # geometry. Primitives that do not declare the extension are unaffected by this setting. Type:
    # EdgeDisplayMode.
    edge_display_mode: rx.Var[float]

    # The {@link ClippingPlaneCollection} used to selectively disable rendering the model. Type:
    # ClippingPlaneCollection.
    clipping_planes: rx.Var[Any]

    # The {@link ClippingPolygonCollection} used to selectively disable rendering the model. Type:
    # ClippingPolygonCollection.
    clipping_polygons: rx.Var[Any]

    # The directional light color when shading the model. When <code>undefined</code> the scene's
    # light color is used instead. <p> Disabling additional light sources by setting
    # <code>model.imageBasedLighting.imageBasedLightingFactor = new Cartesian2(0.0, 0.0)</code>
    # will make the model much darker. Here, increasing the intensity of the light source will
    # make the model brighter. </p> Type: Cartesian3.
    light_color: rx.Var[Any]

    # Value used to determine the color strength when the <code>colorBlendMode</code> is
    # <code>MIX</code>. A value of 0.0 results in the model's rendered color while a value of 1.0
    # results in a solid color, with any value in-between resulting in a mix of the two. Type:
    # number.
    color_blend_amount: rx.Var[float]

    # Defines how the color blends with the model. Type: Cesium3DTileColorBlendMode |
    # ColorBlendMode.
    color_blend_mode: rx.Var[float]

    # This property is for debugging only; it is not for production use nor is it optimized. <p>
    # Draws the model in wireframe. </p> Type: boolean.
    debug_wireframe: rx.Var[bool]

    # The style to apply to the features in the model. Cannot be applied if a {@link CustomShader}
    # is also applied. Type: Cesium3DTileStyle.
    cesium_style: rx.Var[Any]

    # Whether to cull back-facing geometry. When true, back face culling is determined by the
    # material's doubleSided property; when false, back face culling is disabled. Back faces are
    # not culled if {@link Model#color } is translucent or {@link Model#silhouetteSize } is
    # greater than 0.0. Type: boolean.
    back_face_culling: rx.Var[bool]

    # Whether to display the outline for models using the {@link https://github.com/KhronosGroup/g
    # lTF/tree/master/extensions/2.0/Vendor/CESIUM_primitive_outline CESIUM_primitive_outline}
    # extension. When true, outlines are displayed. When false, outlines are not displayed. Type:
    # boolean.
    show_outline: rx.Var[bool]

    # The model's custom shader, if it exists. Using custom shaders with a {@link
    # Cesium3DTileStyle} may lead to undefined behavior. Type: CustomShader.
    custom_shader: rx.Var[Any]

    # The properties for managing image-based lighting on this model. Type: ImageBasedLighting.
    image_based_lighting: rx.Var[Any]

    # Gets or sets whether the credits of the model will be displayed on the screen. Type:
    # boolean.
    show_credits_on_screen: rx.Var[bool]

    # Label of the feature ID set to use for picking and styling. <p> For EXT_mesh_features, this
    # is the feature ID's label property, or "featureId_N" (where N is the index in the featureIds
