class MVTDataProvider(ResiumComponent):
    """Wraps resium ``MVTDataProvider``.

    MVTDataProvider loads Mapbox Vector Tiles (MVT) as runtime-generated 3D Tiles.

    Scope:
      Inside Viewer or CesiumWidget component.
      An MVTDataProvider object will be attached to the PrimitiveCollection of the Viewer or CesiumWidget.

    Docs: https://resium.reearth.io/components/MVTDataProvider
    """

    tag = "MVTDataProvider"

    # Determines if the generated tileset is shown. Type: boolean.
