    # Minimum zoom level represented in the generated tileset. Fixed at creation time. Type:
    # number. Read-only: changing it re-creates the Cesium element.
    min_zoom: rx.Var[float]

    # Maximum zoom level represented in the generated tileset. Fixed at creation time. Type:
    # number. Read-only: changing it re-creates the Cesium element.
    max_zoom: rx.Var[float]

    # Optional geographic extent (radians) constraining the generated tile tree. Fixed at creation
    # time. Type: Rectangle. Read-only: changing it re-creates the Cesium element.
    extent: rx.Var[Any]

    # MVT property name to use as feature ID. Fixed at creation time. Type: string. Read-only:
    # changing it re-creates the Cesium element.
    feature_id_property: rx.Var[str]

    # Drapes the decoded points, lines and polygons onto terrain and/or 3D Tiles (Cesium 1.145+).
    # `CLAMP_TO_TERRAIN` drapes onto terrain, `CLAMP_TO_3D_TILE` onto 3D Tiles, and
    # `CLAMP_TO_GROUND` onto both. Cesium requires a `Scene` for clamping values; resium supplies
    # the enclosing `Viewer`/`CesiumWidget` scene automatically. Fixed at creation time. Type:
    # HeightReference. Read-only: changing it re-creates the Cesium element.
    height_reference: rx.Var[float]

    # Required URL template containing `{z}`/`{x}`/`{y}` placeholders. Type: string | Resource.
    # Required.
    url: rx.Var[Any]

    # onReady(provider: MVTDataProviderShape) — Fires once `fromUrl` resolves. Reach
    # `provider.tileset` (or call `getTileset(provider)`) here to apply clipping/styling.
    on_ready: rx.EventHandler[object_event]

    # onError(err: unknown) — Fires if `fromUrl` rejects.
    on_error: rx.EventHandler[error_event]

    _resium_readonly_props = ('min_zoom', 'max_zoom', 'extent', 'feature_id_property', 'height_reference')


