    # indicated by <code>value</code>'s <code>red</code>, <code>green</code>, <code>blue</code>,
    # and <code>alpha</code> properties as shown in Example 1. These components range from
    # <code>0.0</code> (no intensity) to <code>1.0</code> (full intensity). Type: Color.
    color: rx.Var[Any]

    # Gets or sets the distance from the camera at which to disable the depth test to, for
    # example, prevent clipping against terrain. When set to zero, the depth test is always
    # applied. When set to Number.POSITIVE_INFINITY, the depth test is never applied. Type:
    # number.
