    position: rx.Var[Any]

    # Gets or sets near and far scaling properties of a point based on the point's distance from
    # the camera. A point's scale will interpolate between the {@link NearFarScalar#nearValue }
    # and {@link NearFarScalar#farValue } while the camera distance falls within the lower and
    # upper bounds of the specified {@link NearFarScalar#near } and {@link NearFarScalar#far }.
    # Outside of these ranges the point's scale remains clamped to the nearest bound. This scale
    # multiplies the pixelSize and outlineWidth to affect the total size of the point. If
    # undefined, scaleByDistance will be disabled. Type: NearFarScalar.
    scale_by_distance: rx.Var[Any]

    # Determines if this point will be shown. Use this to hide or show a point, instead of
    # removing it and re-adding it to the collection. Type: boolean.
    show: rx.Var[bool]

