    split_direction: rx.Var[float]

    # Gets or sets near and far translucency properties of a point based on the point's distance
    # from the camera. A point's translucency will interpolate between the {@link
    # NearFarScalar#nearValue } and {@link NearFarScalar#farValue } while the camera distance
    # falls within the lower and upper bounds of the specified {@link NearFarScalar#near } and
    # {@link NearFarScalar#far }. Outside of these ranges the point's translucency remains clamped
    # to the nearest bound. If undefined, translucencyByDistance will be disabled. Type:
    # NearFarScalar.
    translucency_by_distance: rx.Var[Any]

    # Gets or sets the outline color of the point. Type: Color.
    outline_color: rx.Var[Any]

    # Gets or sets the outline width in pixels. This width adds to pixelSize, increasing the total
