class Scene(ResiumComponent):
    """Wraps resium ``Scene``.

    Scene can operate the scene of the Viewer or CesiumWidget. All properties are
    applied to single scene of them.

    Scope:
      Scene can be mounted insideViewer or CesiumWidget components.
      It can not be mounted more than once for each Viewer or CesiumWidget.

    Docs: https://resium.reearth.io/components/Scene
    """

    tag = "Scene"

    # The terrain provider providing surface geometry for the globe. Type: TerrainProvider.
    terrain_provider: rx.Var[Any]

    # The {@link SkyBox} used to draw the stars. Type: SkyBox.
    sky_box: rx.Var[Any]

    # The sky atmosphere drawn around the globe. Type: SkyAtmosphere.
    sky_atmosphere: rx.Var[Any]

    # Gets or sets the depth-test ellipsoid. Type: Globe.
    globe: rx.Var[Any]

    # When <code>true</code>, rendering a frame will only occur when needed as determined by
    # changes within the scene. Enabling improves performance of the application, but requires
    # using {@link Scene#requestRender } to render a new frame explicitly in this mode. This will
    # be necessary in many cases after making changes to the scene in other parts of the API.
    # Type: boolean.
    request_render_mode: rx.Var[bool]

    # If {@link Scene#requestRenderMode } is <code>true</code>, this value defines the maximum
    # change in simulation time allowed before a render is requested. Lower values increase the
    # number of frames rendered and higher values decrease the number of frames rendered. If
    # <code>undefined</code>, changes to the simulation time will never request a render. This
    # value impacts the rate of rendering for changes in the scene like lighting, entity property
    # updates, and animations. Type: number.
    maximum_render_time_change: rx.Var[float]

    # The sample rate of multisample antialiasing (values greater than 1 enable MSAA). Type:
    # number.
    msaa_samples: rx.Var[float]

    # The value used for gamma correction. This is only used when rendering with high dynamic
    # range. Type: number.
    gamma: rx.Var[float]

    # The background color, which is only visible if there is no sky box, i.e., {@link
    # Scene#skyBox } is <code>undefined</code>. Type: Color.
    background_color: rx.Var[Any]

    # The vertical exaggeration of the scene. When set to 1.0, no exaggeration is applied. Type:
    # number.
    vertical_exaggeration: rx.Var[float]

    # Determines whether or not to instantly complete the scene transition animation on user
    # input. Type: boolean.
    complete_morph_on_user_input: rx.Var[bool]

    # This property is for debugging only; it is not for production use. <p> When
    # <code>true</code>, commands are randomly shaded. This is useful for performance analysis to
    # see what parts of a scene or model are command-dense and could benefit from batching. </p>
    # Type: boolean.
    debug_show_commands: rx.Var[bool]

    # This property is for debugging only; it is not for production use. <p> Indicates which
    # frustum will have depth information displayed. </p> Type: number.
    debug_show_depth_frustum: rx.Var[float]

    # This property is for debugging only; it is not for production use. <p> Displays frames per
    # second and time between frames. </p> Type: boolean.
    debug_show_frames_per_second: rx.Var[bool]

    # This property is for debugging only; it is not for production use. <p> When
    # <code>true</code>, draws outlines to show the boundaries of the camera frustums </p> Type:
    # boolean.
    debug_show_frustum_planes: rx.Var[bool]

    # This property is for debugging only; it is not for production use. <p> When
    # <code>true</code>, commands are shaded based on the frustums they overlap. Commands in the
    # closest frustum are tinted red, commands in the next closest are green, and commands in the
    # farthest frustum are blue. If a command overlaps more than one frustum, the color components
    # are combined, e.g., a command overlapping the first two frustums is tinted yellow. </p>
    # Type: boolean.
    debug_show_frustums: rx.Var[bool]

    # The eye separation distance in meters for use with cardboard or WebVR. Type: number.
    eye_separation: rx.Var[float]

    # The far-to-near ratio of the multi-frustum when using a normal depth buffer. <p> This value
    # is used to create the near and far values for each frustum of the multi-frustum. It is only
    # used when {@link Scene#logarithmicDepthBuffer } is <code>false</code>. When
    # <code>logarithmicDepthBuffer</code> is <code>true</code>, use {@link
    # Scene#logarithmicDepthFarToNearRatio }. </p> Type: number.
    far_to_near_ratio: rx.Var[float]

    # The focal length for use when with cardboard or WebVR. Type: number.
    focal_length: rx.Var[float]

    # Blends the atmosphere to geometry far from the camera for horizon views. Allows for
    # additional performance improvements by rendering less geometry and dispatching less terrain
    # requests. Disbaled by default if an ellipsoid other than WGS84 is used. Type: Fog.
    fog: rx.Var[Any]

    # Whether or not to use high dynamic range rendering. Type: boolean.
    high_dynamic_range: rx.Var[bool]

    # When <code>false</code>, 3D Tiles will render normally. When <code>true</code>, classified
    # 3D Tile geometry will render normally and unclassified 3D Tile geometry will render with the
    # color multiplied by {@link Scene#invertClassificationColor }. Type: boolean.
    invert_classification: rx.Var[bool]

    # The highlight color of unclassified 3D Tile geometry when {@link Scene#invertClassification
    # } is <code>true</code>. <p>When the color's alpha is less than 1.0, the unclassified
    # portions of the 3D Tiles will not blend correctly with the classified positions of the 3D
    # Tiles.</p> <p>Also, when the color's alpha is less than 1.0, the WEBGL_depth_texture and
    # EXT_frag_depth WebGL extensions must be supported.</p> Type: Color.
    invert_classification_color: rx.Var[Any]

    # The light source for shading. Defaults to a directional light from the Sun. Type: Light.
    light: rx.Var[Any]

    # Whether or not to use a logarithmic depth buffer. Enabling this option will allow for less
    # frustums in the multi-frustum, increasing performance. This property relies on fragmentDepth
    # being supported. Type: boolean.
    logarithmic_depth_buffer: rx.Var[bool]

    # The far-to-near ratio of the multi-frustum when using a logarithmic depth buffer. <p> This
    # value is used to create the near and far values for each frustum of the multi-frustum. It is
    # only used when {@link Scene#logarithmicDepthBuffer } is <code>true</code>. When
    # <code>logarithmicDepthBuffer</code> is <code>false</code>, use {@link Scene#farToNearRatio
    # }. </p> Type: number.
    logarithmic_depth_far_to_near_ratio: rx.Var[float]

    # The distance from the camera at which to disable the depth test of billboards, labels and
    # points to, for example, prevent clipping against terrain. When set to zero, the depth test
    # should always be applied. When less than zero, the depth test should never be applied.
    # Setting the disableDepthTestDistance property of a billboard, label or point will override
    # this value. Type: number.
    minimum_disable_depth_test_distance: rx.Var[float]

    # The {@link Moon} Type: Moon.
    moon: rx.Var[Any]

    # The current morph transition time between 2D/Columbus View and 3D, with 0.0 being 2D or
    # Columbus View and 1.0 being 3D. Type: number.
    morph_time: rx.Var[float]

    # Determines the uniform depth size in meters of each frustum of the multifrustum in 2D. If a
    # primitive or model close to the surface shows z-fighting, decreasing this will eliminate the
    # artifact, but decrease performance. On the other hand, increasing this will increase
    # performance but may cause z-fighting among primitives close to the surface. Type: number.
    near_to_far_distance2_d: rx.Var[float]

    # When <code>true</code>, enables picking translucent geometry using the depth buffer. Note
    # that {@link Scene#useDepthPicking } must also be true for enabling this to work. <p> There
    # is a decrease in performance when enabled. There are extra draw calls to write depth for
    # translucent geometry. </p> Type: boolean.
    pick_translucent_depth: rx.Var[bool]

    # Exceptions occurring in <code>render</code> are always caught in order to raise the
    # <code>renderError</code> event. If this property is true, the error is rethrown after the
    # event is raised. If this property is false, the <code>render</code> function returns
    # normally after raising the event. Type: boolean.
    rethrow_render_errors: rx.Var[bool]

    # The shadow map for the scene's light source. When enabled, models, primitives, and the globe
    # may cast and receive shadows. Type: ShadowMap.
    shadow_map: rx.Var[Any]

    # The url to the KTX2 file containing the specular environment map and convoluted mipmaps for
    # image-based lighting of PBR models. Type: string.
    specular_environment_maps: rx.Var[str]

    # The spherical harmonic coefficients for image-based lighting of PBR models. Type:
    # Cartesian3[].
    spherical_harmonic_coefficients: rx.Var[Any]

    # The {@link Sun}. Type: Sun.
    sun: rx.Var[Any]

    # Uses a bloom filter on the sun when enabled. Type: boolean.
    sun_bloom: rx.Var[bool]

    # When <code>true</code>, enables picking using the depth buffer. Type: boolean.
    use_depth_picking: rx.Var[bool]

    # When <code>true</code>, splits the scene into two viewports with steroscopic views for the
    # left and right eyes. Used for cardboard and WebVR. Type: boolean.
    use_web_vr: rx.Var[bool]

    # Gets or sets the position of the splitter within the viewport. Valid values are between 0.0
    # and 1.0. Type: number.
    split_position: rx.Var[float]

    # The reference height for vertical exaggeration of the scene. When set to 0.0, the
    # exaggeration is applied relative to the ellipsoid surface. Type: number.
    vertical_exaggeration_relative_height: rx.Var[float]

    # Settings for atmosphere lighting effects affecting 3D Tiles and model rendering. This is not
    # to be confused with {@link Scene#skyAtmosphere } which is responsible for rendering the sky.
    # Type: Atmosphere.
    atmosphere: rx.Var[Any]

    # Type: SceneMode.
    mode: rx.Var[float]

    # If this prop is set and when `mode` prop is changed, the scene morphs with this duration
    # (seconds). Type: number.
    morph_duration: rx.Var[float]

    # Whether or not to enable edge visibility rendering for 3D tiles. When enabled, creates a
    # framebuffer with multiple render targets for advanced edge detection and visibility
    # techniques. Maps to Cesium's internal `_enableEdgeVisibility` property. Type: boolean.
    enable_edge_visibility: rx.Var[bool]

    # onMorphComplete()
    on_morph_complete: rx.EventHandler[no_args_event]

    # onMorphStart()
    on_morph_start: rx.EventHandler[no_args_event]

    # onPostRender()
    on_post_render: rx.EventHandler[no_args_event]

    # onPreRender()
    on_pre_render: rx.EventHandler[no_args_event]

    # onPreUpdate()
    on_pre_update: rx.EventHandler[no_args_event]

    # onPostUpdate()
    on_post_update: rx.EventHandler[no_args_event]

    # onRenderError()
    on_render_error: rx.EventHandler[no_args_event]

    # onTerrainProviderChange()
    on_terrain_provider_change: rx.EventHandler[no_args_event]

    _resium_renamed_props = {'use_web_vr': 'useWebVR'}


scene = Scene.create


class ScreenSpaceCameraController(ResiumComponent):
    """Wraps resium ``ScreenSpaceCameraController``.

    ScreenSpaceCameraController can change how to operate the camera of the scene. All
    properties are applied to single ScreenSpaceCameraController in the scene.

    Scope:
      ScreenSpaceCameraController can be mounted insideViewer or CesiumWidget components.
      It can not be mounted more than once for each Viewer or CesiumWidget.

    Docs: https://resium.reearth.io/components/ScreenSpaceCameraController
    """

    tag = "ScreenSpaceCameraController"

    # Sets the duration, in seconds, of the bounce back animations in 2D and Columbus view. Type:
    # number.
    bounce_animation_time: rx.Var[float]

    # When disabled, the values of <code>maximumZoomDistance</code> and
    # <code>minimumZoomDistance</code> are ignored. Also used in conjunction with {@link
    # Cesium3DTileset#enableCollision } to prevent the camera from moving through or below a 3D
    # Tileset surface. This may also affect clamping behavior when using {@link
    # HeightReference.CLAMP_TO_GROUND} on 3D Tiles. Type: boolean.
    enable_collision_detection: rx.Var[bool]

    # If true, inputs are allowed conditionally with the flags enableTranslate, enableZoom,
    # enableRotate, enableTilt, and enableLook. If false, all inputs are disabled. NOTE: This
    # setting is for temporary use cases, such as camera flights and drag-selection of regions
    # (see Picking demo). It is typically set to false at the start of such events, and set true
    # on completion. To keep inputs disabled past the end of camera flights, you must use the
    # other booleans (enableTranslate, enableZoom, enableRotate, enableTilt, and enableLook).
    # Type: boolean.
    enable_inputs: rx.Var[bool]

    # If true, allows the user to use free-look. If false, the camera view direction can only be
    # changed through translating or rotating. This flag only applies in 3D and Columbus view
    # modes. Type: boolean.
    enable_look: rx.Var[bool]

    # If true, allows the user to rotate the world which translates the user's position. This flag
    # only applies in 2D and 3D. Type: boolean.
    enable_rotate: rx.Var[bool]

    # If true, allows the user to tilt the camera. If false, the camera is locked to the current
    # heading. This flag only applies in 3D and Columbus view. Type: boolean.
    enable_tilt: rx.Var[bool]

    # If true, allows the user to pan around the map. If false, the camera stays locked at the
    # current position. This flag only applies in 2D and Columbus view modes. Type: boolean.
    enable_translate: rx.Var[bool]

    # If true, allows the user to zoom in and out. If false, the camera is locked to the current
    # distance from the ellipsoid. Type: boolean.
    enable_zoom: rx.Var[bool]

    # A parameter in the range <code>[0, 1)</code> used to determine how long the camera will
    # continue to spin because of inertia. With value of zero, the camera will have no inertia.
    # Type: number.
    inertia_spin: rx.Var[float]

    # A parameter in the range <code>[0, 1)</code> used to determine how long the camera will
    # continue to translate because of inertia. With value of zero, the camera will have no
    # inertia. Type: number.
    inertia_translate: rx.Var[float]

    # A parameter in the range <code>[0, 1)</code> used to determine how long the camera will
    # continue to zoom because of inertia. With value of zero, the camera will have no inertia.
    # Type: number.
    inertia_zoom: rx.Var[float]

    # The input that allows the user to change the direction the camera is viewing. This only
    # applies in 3D and Columbus view modes. <p> The type can be a {@link CameraEventType},
    # <code>undefined</code>, an object with <code>eventType</code> and <code>modifier</code>
    # properties with types <code>CameraEventType</code> and {@link KeyboardEventModifier}, or an
    # array of any of the preceding. </p> Type: any[] | CameraEventType.
    look_event_types: rx.Var[Any]

    # A parameter in the range <code>[0, 1)</code> used to limit the range of various user inputs
    # to a percentage of the window width/height per animation frame. This helps keep the camera
    # under control in low-frame-rate situations. Type: number.
    maximum_movement_ratio: rx.Var[float]

    # The maximum magnitude, in meters, of the camera position when zooming. Defaults to positive
    # infinity. Type: number.
    maximum_zoom_distance: rx.Var[float]

    # The minimum height the camera must be before testing for collision with terrain. Default to
    # scene.ellipsoid.minimumRadius * 0.0025 when another ellipsoid than WGS84 is used. Type:
    # number.
    minimum_collision_terrain_height: rx.Var[float]

    # The minimum height the camera must be before picking the terrain or scene content instead of
    # the ellipsoid. Defaults to scene.ellipsoid.minimumRadius * 0.025 when another ellipsoid than
    # WGS84 is used. Type: number.
    minimum_picking_terrain_height: rx.Var[float]

    # The minimum height the camera must be before switching from rotating a track ball to free
    # look when clicks originate on the sky or in space. Defaults to ellipsoid.minimumRadius *
    # 1.175 when another ellipsoid than WGS84 is used. Type: number.
    minimum_track_ball_height: rx.Var[float]

    # The minimum magnitude, in meters, of the camera position when zooming. Defaults to 1.0.
    # Type: number.
    minimum_zoom_distance: rx.Var[float]

    # The input that allows the user to rotate around the globe or another object. This only
    # applies in 3D and Columbus view modes. <p> The type can be a {@link CameraEventType},
    # <code>undefined</code>, an object with <code>eventType</code> and <code>modifier</code>
    # properties with types <code>CameraEventType</code> and {@link KeyboardEventModifier}, or an
    # array of any of the preceding. </p> Type: any[] | CameraEventType.
    rotate_event_types: rx.Var[Any]

    # The input that allows the user to tilt in 3D and Columbus view or twist in 2D. <p> The type
    # can be a {@link CameraEventType}, <code>undefined</code>, an object with
    # <code>eventType</code> and <code>modifier</code> properties with types
    # <code>CameraEventType</code> and {@link KeyboardEventModifier}, or an array of any of the
    # preceding. </p> Type: any[] | CameraEventType.
    tilt_event_types: rx.Var[Any]

    # The input that allows the user to pan around the map. This only applies in 2D and Columbus
    # view modes. <p> The type can be a {@link CameraEventType}, <code>undefined</code>, an object
    # with <code>eventType</code> and <code>modifier</code> properties with types
    # <code>CameraEventType</code> and {@link KeyboardEventModifier}, or an array of any of the
    # preceding. </p> Type: any[] | CameraEventType.
    translate_event_types: rx.Var[Any]

    # The input that allows the user to zoom in/out. <p> The type can be a {@link
    # CameraEventType}, <code>undefined</code>, an object with <code>eventType</code> and
    # <code>modifier</code> properties with types <code>CameraEventType</code> and {@link
    # KeyboardEventModifier}, or an array of any of the preceding. </p> Type: any[] |
    # CameraEventType.
    zoom_event_types: rx.Var[Any]

    # The minimum distance the camera must be before testing for collision with terrain when zoom
    # with inertia. Default to scene.ellipsoid.minimumRadius * 0.00063 when another ellipsoid than
    # WGS84 is used. Type: number.
    minimum_picking_terrain_distance_with_inertia: rx.Var[float]

    # The angle, relative to the ellipsoid normal, restricting the maximum amount that the user
    # can tilt the camera. If <code>undefined</code>, the angle of the camera tilt is
    # unrestricted. Type: number.
    maximum_tilt_angle: rx.Var[float]

    # A multiplier for the speed at which the camera will zoom. Type: number.
    zoom_factor: rx.Var[float]


screen_space_camera_controller = ScreenSpaceCameraController.create


class ScreenSpaceElevatorCameraController(ResiumComponent):
    """Wraps resium ``ScreenSpaceElevatorCameraController``.

    ScreenSpaceElevatorCameraController pans the camera vertically, as if riding an
    elevator, which suits inspecting the facade of a building or another tall asset. It
    is one of the alternative camera controllers added in Cesium 1.144, built on the
    composable Controller framework.

    Scope:
      Inside Viewer or CesiumWidget components.
      The controller is registered with the scene's ControllerHost.

    Docs: https://resium.reearth.io/components/ScreenSpaceElevatorCameraController
    """

