    # Determines if the controller is enabled and should be updated by the host scene. Type:
    # boolean.
    enabled: rx.Var[bool]

    # A parameter in the range <code>[0, 1)</code> used to limit the range of inputs to a
    # percentage of the window width/height per animation frame. This helps keep the camera under
    # control in low-frame-rate situations. Type: number.
    maximum_movement_ratio: rx.Var[float]

    # Enable or disable inertia when panning. When enabled, the camera will continue to move after
    # the user stops dragging, gradually slowing down based on {@link
    # ScreenSpaceMapCameraController#inertialDecay }. Type: boolean.
    inertia_enabled: rx.Var[bool]

