    # Cartesian3} instance to store the result. The function should return the {@link Cartesian3}
    # world position from which to pan, or <code>undefined</code> if no position could be picked.
    # If <code>undefined</code> is returned, the camera will pan relative to the ellipsoid surface
    # below the camera. Type: ((...params: any[]) => any).
    pick_world_position: rx.Var[Any]

    # Mouse button and optional keyboard modifier combinations that start a vertical pan. Bindings
    # are attached once when the controller is registered, so changing this prop re-creates the
    # controller rather than mutating it in place. Type: InputBinding[]. Read-only: changing it
    # re-creates the Cesium element.
    drag_inputs: rx.Var[Any]

    # Precedence relative to other registered controllers. `0` applies before every other
    # controller; omitting it makes this controller the highest priority. Changing this prop re-
    # registers the controller. Type: number. Read-only: changing it re-creates the Cesium
    # element.
    priority: rx.Var[float]

