    # A parameter in the range <code>[0, 1)</code> used to limit the range of inputs to a
    # percentage of the window width/height per animation frame. This helps keep the camera under
    # control in low-frame-rate situations. Type: number.
    maximum_movement_ratio: rx.Var[float]

    # A callback function used to pick the world position around which to tilt or orbit. The
