    # The maximum tilt velocity in radians per second. A value of Number.POSITIVE_INFINITY means
    # that the maximum tilt velocity is unbounded. Type: number.
    maximum_tilt_velocity: rx.Var[float]

    # Specifies the length of time in seconds in which a single orbit animation completes. Type:
    # number.
    orbit_animation_duration: rx.Var[float]

    # Enabled dragging to orbit the camera. Type: boolean.
