class Viewer(ResiumComponent):
    """Wraps resium ``Viewer``.

    Viewer is a root component of resium same as CesiumWidget. All components of resium
    except the root components have to be mounted inside it.

    Scope:
      Everywhere. Viewer is a root component.

    Docs: https://resium.reearth.io/components/Viewer
    """

    tag = "Viewer"

    # Determines if shadows are cast by light sources. Type: boolean.
    shadows: rx.Var[bool]

    # Gets or sets a scaling factor for rendering resolution. Values less than 1.0 can improve
    # performance on less powerful devices while values greater than 1.0 will render at a higher
    # resolution and then scale down, resulting in improved visual fidelity. For example, if the
    # widget is laid out at a size of 640x480, setting this value to 0.5 will cause the scene to
    # be rendered at 320x240 and then scaled up while setting it to 2.0 will cause the scene to be
    # rendered at 1280x960 and then scaled down. Type: number.
    resolution_scale: rx.Var[float]

    # Gets or sets whether or not this widget should control the render loop. If true the widget
    # will use requestAnimationFrame to perform rendering and resizing of the widget, as well as
    # drive the simulation clock. If set to false, you must manually call the <code>resize</code>,
    # <code>render</code> methods as part of a custom render loop. If an error occurs during
    # rendering, {@link Scene}'s <code>renderError</code> event will be raised and this property
    # will be set to false. It must be set back to true to continue rendering after the error.
    # Type: boolean.
    use_default_render_loop: rx.Var[bool]

    # Gets or sets the target frame rate of the widget when <code>useDefaultRenderLoop</code> is
    # true. If undefined, the browser's requestAnimationFrame implementation determines the frame
    # rate. If defined, this value must be greater than 0. A value higher than the underlying
    # requestAnimationFrame implementation will have no effect. Type: number.
    target_frame_rate: rx.Var[float]

    # Boolean flag indicating if the browser's recommended resolution is used. If true, the
    # browser's device pixel ratio is ignored and 1.0 is used instead, effectively rendering based
    # on CSS pixels instead of device pixels. This can improve performance on less powerful
    # devices that have high pixel density. When false, rendering will be in device pixels. {@link
    # Viewer#resolutionScale } will still take effect whether this flag is true or false. Type:
    # boolean.
    use_browser_recommended_resolution: rx.Var[bool]

    # Gets or sets whether or not data sources can temporarily pause animation in order to avoid
    # showing an incomplete picture to the user. For example, if asynchronous primitives are being
    # processed in the background, the clock will not advance until the geometry is ready. Type:
    # boolean.
    allow_data_sources_to_suspend_animation: rx.Var[bool]

