class WebMapTileServiceImageryProvider(ResiumComponent):
    """Wraps resium ``WebMapTileServiceImageryProvider``.

    WebMapTileServiceImageryProvider provides tiled imagery served by WMTS 1.0.0
    compliant servers. Supports HTTP KVP-encoded and RESTful GetTile requests.

    Scope:
      Inside ImageryLayer component.

    Docs: https://resium.reearth.io/components/WebMapTileServiceImageryProvider
    """

    tag = "WebMapTileServiceImageryProvider"

    # The base URL for the WMTS GetTile operation (for KVP-encoded requests) or the tile-URL
    # template (for RESTful requests). Type: string | Resource. Required.
    url: rx.Var[Any]

    # The layer name for WMTS requests. Type: string. Required.
    layer: rx.Var[str]

    # The style name for WMTS requests. Type: string. Required.
    cesium_style: rx.Var[str]

    # The identifier of the TileMatrixSet to use for WMTS requests. Type: string. Required.
    tile_matrix_set_id: rx.Var[str]

    # The MIME type for images to retrieve from the server. Defaults to 'image/jpeg'. Type:
    # string.
    format: rx.Var[str]

    # The tiling scheme corresponding to the organization of the tiles in the TileMatrixSet. Type:
    # TilingScheme.
    tiling_scheme: rx.Var[Any]

    # The rectangle covered by the layer. Type: Rectangle.
    rectangle: rx.Var[Any]

    # The minimum level-of-detail supported by the imagery provider. Type: number.
    minimum_level: rx.Var[float]

    # The maximum level-of-detail supported by the imagery provider, or undefined if there is no
    # limit. Type: number.
    maximum_level: rx.Var[float]

    # The ellipsoid. If not specified, the WGS84 ellipsoid is used. Type: Ellipsoid.
    ellipsoid: rx.Var[Any]

    # A credit for the data source, which is displayed on the canvas. Type: string | Credit.
    credit: rx.Var[Any]

    # Additional parameters to include in GetTile requests. Type: Record<string, string | number |
    # boolean>.
    parameters: rx.Var[Any]

    # If true, pickFeatures will invoke the GetFeatureInfo service on the WMTS server. Type:
    # boolean.
    enable_pick_features: rx.Var[bool]

    # The formats in which to try WMTS GetFeatureInfo requests. Type: GetFeatureInfoFormat[].
    get_feature_info_formats: rx.Var[Any]

    # The GetFeatureInfo URL of the WMTS service. If not specified, the value of url is used.
    # Type: string | Resource.
    get_feature_info_url: rx.Var[Any]

    # Additional parameters to include in GetFeatureInfo requests. Type: Record<string, string |
    # number | boolean>.
    get_feature_info_parameters: rx.Var[Any]

    # onReady(provider: WebMapTileServiceImageryProvider) — Calls when the imagery provider is
    # successfully created.
    on_ready: rx.EventHandler[object_event]

    _resium_renamed_props = {'cesium_style': 'style', 'tile_matrix_set_id': 'tileMatrixSetID'}


web_map_tile_service_imagery_provider = WebMapTileServiceImageryProvider.create


